package com.prometheus.clq.data

import com.prometheus.clq.model.Difficulty
import com.prometheus.clq.model.Question

object QuestionsExpansion21 {
    fun get(): List<Question> = listOf(
        // SPORT (50 questions) - IDs 13100-13149
        Question(13100, "Quel pays accueille traditionnellement les Jeux Olympiques d'hiver?", listOf("Suisse", "Japon", "Variable selon l'année", "Canada"), 2, "Sport", Difficulty.EASY, explanation = "Les Jeux Olympiques d'hiver changent de pays hôte à chaque édition, selon le choix du Comité International Olympique. Aucun pays n'est fixe, contrairement aux Jeux antiques."),
        Question(13101, "En water-polo, combien de joueurs sont présents par équipe dans l'eau?", listOf("5", "6", "7", "8"), 2, "Sport", Difficulty.MEDIUM, explanation = "Au water-polo, chaque équipe aligne 7 joueurs dans l'eau : 6 joueurs de champ et 1 gardien de but."),
        Question(13102, "Le ski de fond est une discipline olympique d'hiver. Quel est le pays dominant historiquement?", listOf("Suède", "Norvège", "Finlande", "Russie"), 1, "Sport", Difficulty.MEDIUM, explanation = "La Norvège domine historiquement le ski de fond aux Jeux olympiques d'hiver, avec le plus grand nombre de médailles dans cette discipline, grâce à une forte culture du ski et des conditions naturelles favorables."),
        Question(13103, "En aviron, comment appelle-t-on l'athlète qui donne le rythme?", listOf("Le barreur", "Le meneur", "Le chef", "Le capitaine"), 0, "Sport", Difficulty.HARD, explanation = "Le barreur est l'athlète assis à l'arrière du bateau qui dirige l'équipage et donne le rythme des coups de rame."),
        Question(13104, "Le curling est un sport d'hiver. Quel équipement glissant est lancé sur la glace?", listOf("Une pierre", "Une boule", "Un palet", "Une rondelle"), 0, "Sport", Difficulty.MEDIUM, explanation = "Au curling, les joueurs lancent des pierres en granite, appelées \"pierres de curling\", qui glissent sur la glace vers une cible circulaire."),
        Question(13105, "Combien de cibles différentes sont utilisées au tir à l'arc olympique?", listOf("1", "2", "3", "4"), 0, "Sport", Difficulty.HARD, explanation = "Au tir à l'arc olympique, tous les archers tirent sur le même type de cible, une cible circulaire de 122 cm de diamètre avec 10 zones concentriques."),
        Question(13106, "Le pentathlon moderne comprend 5 épreuves. Laquelle n'en fait pas partie?", listOf("Tir", "Escrime", "Natation", "Haltérophilie"), 3, "Sport", Difficulty.HARD, explanation = "Le pentathlon moderne combine escrime, natation, équitation, tir et course à pied, sans inclure l'haltérophilie."),
        Question(13107, "En Formule 1, combien de points rapporte une victoire depuis 2003?", listOf("10", "15", "20", "25"), 2, "Sport", Difficulty.MEDIUM, explanation = "Depuis 2003, le barème de points en Formule 1 attribue 25 points au vainqueur, mais le système actuel est entré en vigueur en 2010, avec 25 points pour une victoire. La réponse 20 correspond à l'ancien barème en vigueur de 2003 à 2009."),
        Question(13108, "Quel sport mécaniste implique une moto et un Side-car?", listOf("Motocross", "Speedway", "Sidecar racing", "Trial"), 2, "Sport", Difficulty.HARD, explanation = "Le sidecar racing est une discipline de course moto où une moto est équipée d'un side-car, un passager (le \"sidecariste\") aidant à la stabilité dans les virages."),
        Question(13109, "Le bobsleigh est une discipline d'hiver. Combien d'athlètes composent une équipe standard?", listOf("2", "3", "4", "5"), 2, "Sport", Difficulty.MEDIUM, explanation = "En compétition officielle, un équipage de bobsleigh est composé de quatre athlètes : un pilote, un freineur et deux pousseurs."),
        Question(13110, "En patinage de vitesse, quel est le défi principal du patineur?", listOf("Garder l'équilibre", "Minimiser les frottements", "Maximiser la force", "Augmenter le poids"), 1, "Sport", Difficulty.HARD, explanation = "En patinage de vitesse, la performance dépend de la capacité à réduire la résistance de l'air et la friction sur la glace, ce qui permet d'atteindre des vitesses plus élevées avec moins d'effort."),
        Question(13111, "Le rallye automobile est une compétition sur routes. Qui guide le pilote?", listOf("Un co-pilote", "Une GPS", "Un radar", "Un observateur"), 0, "Sport", Difficulty.MEDIUM, explanation = "Le co-pilote lit le carnet de notes (road book) et annonce les virages et obstacles au pilote, permettant de négocier le parcours à haute vitesse sur routes fermées."),
        Question(13112, "En hockey sur glace, combien de joueurs sont sur la glace par équipe simultanément?", listOf("4", "5", "6", "7"), 2, "Sport", Difficulty.EASY, explanation = "Au hockey sur glace, chaque équipe aligne six joueurs sur la glace : trois attaquants, deux défenseurs et un gardien de but."),
        Question(13113, "Le biathlon combine le ski de fond et quel autre sport?", listOf("Le tir au fusil", "Le tir au pistolet", "Le tir à l'arc", "Le saut à ski"), 0, "Sport", Difficulty.MEDIUM, explanation = "Le biathlon est une discipline olympique qui alterne des tours de ski de fond et des séances de tir sur cibles avec un fusil à air comprimé ou à petit calibre."),
        Question(13114, "En aviron, quel type de bateau utilise 8 rameurs?", listOf("Le single", "Le double", "Le quatre", "L'eight"), 3, "Sport", Difficulty.HARD, explanation = "En aviron, un bateau avec huit rameurs est appelé un \"eight\" ou \"huit de pointe\", car chaque rameur manie une seule rame."),
        Question(13115, "Le skeleton est une discipline d'hiver où l'athlète se couche. Sur quel équipement?", listOf("Une luge", "Un traineau", "Une planche", "Un siège"), 1, "Sport", Difficulty.HARD, explanation = "Le skeleton se pratique sur un traîneau spécifique, sans freins ni direction, où l'athlète descend la tête la première sur une piste de glace."),
        Question(13116, "Quel sport combine la danse et le patinage sur glace?", listOf("Patinage artistique", "Patinage synchronisé", "Patinage de couple", "Patinage libre"), 0, "Sport", Difficulty.EASY, explanation = "Le patinage artistique est un sport où les patineurs exécutent des sauts, des pirouettes et des pas de danse sur la glace, notés sur des critères techniques et artistiques."),
        Question(13117, "En tir à l'arc, quelle distance est la plus longue aux Jeux Olympiques?", listOf("30 mètres", "50 mètres", "70 mètres", "100 mètres"), 2, "Sport", Difficulty.HARD, explanation = "Aux Jeux Olympiques, les épreuves de tir à l'arc se déroulent sur une distance réglementaire de 70 mètres, que ce soit pour les qualifications ou les phases finales."),
        Question(13118, "Le water-polo se joue dans une piscine. Quelle est la profondeur minimale?", listOf("1,5 m", "1,8 m", "2 m", "2,5 m"), 2, "Sport", Difficulty.HARD, explanation = "La profondeur minimale de 2 mètres empêche les joueurs de toucher le fond, ce qui garantit une nage continue et évite les avantages déloyaux."),
        Question(13119, "En sports mécaniques, le MotoGP est la catégorie reine. Quel est le cylindrage maximal?", listOf("500 cc", "750 cc", "1000 cc", "1250 cc"), 2, "Sport", Difficulty.HARD, explanation = "Depuis 2012, le règlement du MotoGP impose un moteur quatre temps d'une cylindrée maximale de 1000 cm³ pour la catégorie reine."),
        Question(13120, "Le saut à ski est une discipline d'hiver. Sur quel type de pente?", listOf("Une montagne", "Un tremplin", "Une colline", "Une vallée"), 1, "Sport", Difficulty.MEDIUM, explanation = "Le saut à ski s'effectue depuis un tremplin, une structure inclinée conçue pour propulser le skieur dans les airs."),
        Question(13121, "En curling, comment appelle-t-on le joueur qui pousse la pierre?", listOf("Le lançeur", "Le pousseur", "Le glisseur", "Le conducteur"), 0, "Sport", Difficulty.HARD, explanation = "Au curling, le lançeur est le joueur qui pousse la pierre sur la glace pour la faire glisser vers la cible, tandis que les coéquipiers balayent pour influencer sa trajectoire."),
        Question(13122, "Le luge est une discipline d'hiver. L'athlète se couche-t-il sur le dos ou le ventre?", listOf("Sur le dos", "Sur le ventre", "Sur le côté", "Assis"), 0, "Sport", Difficulty.MEDIUM, explanation = "En luge, l'athlète se couche sur le dos, les pieds en avant, pour optimiser l'aérodynamisme et le contrôle de la trajectoire."),
        Question(13123, "En pentathlon moderne, l'escrime se pratique avec quelle arme?", listOf("L'épée", "Le fleuret", "Le sabre", "La dague"), 0, "Sport", Difficulty.HARD, explanation = "Au pentathlon moderne, l'escrime se pratique exclusivement à l'épée, car cette arme permet des touches sur tout le corps et simplifie l'arbitrage."),
        Question(13124, "Le beach-volley se joue sur le sable. Combien de joueurs par équipe?", listOf("2", "3", "4", "6"), 0, "Sport", Difficulty.EASY, explanation = "Le beach-volley oppose deux équipes de deux joueurs chacune, contrairement au volley-ball en salle qui en compte six."),
        Question(13125, "En aviron de compétition, quel terme désigne l'ensemble des rameurs?", listOf("L'équipe", "L'équipage", "La formation", "Le groupe"), 1, "Sport", Difficulty.HARD, explanation = "En aviron, l'équipage désigne le groupe de rameurs qui composent un bateau, chaque membre ayant un rôle spécifique (comme le barreur ou les rameurs)."),
        Question(13126, "Le bobsleigh emprunte des éléments à quel autre sport hivernal?", listOf("Luge", "Skeleton", "Skeleton et Luge", "Ski alpin"), 2, "Sport", Difficulty.HARD, explanation = "Le bobsleigh, le skeleton et la luge partagent la même piste de glace et utilisent des luges, mais le bobsleigh se distingue par son équipage et sa coque fermée."),
        Question(13127, "En tir à l'arc, quel type de viseur n'est PAS autorisé?", listOf("Viseur optique", "Viseur instinctif", "Pointeur laser", "Viseur mécanique"), 2, "Sport", Difficulty.HARD, explanation = "Les pointes laser sont interdites en compétition car elles offrent un avantage déloyal en projetant un point lumineux sur la cible, contrairement aux viseurs mécaniques ou optiques standards."),
        Question(13128, "Le snowboard cross oppose combien de concurrents par manche?", listOf("2", "4", "6", "8"), 1, "Sport", Difficulty.MEDIUM, explanation = "Le snowboard cross se déroule en séries éliminatoires de quatre concurrents qui s'affrontent simultanément sur un parcours de bosses, virages et sauts."),
        Question(13129, "En cyclisme, quel terrain accueille les plus grands championnats de VTT?", listOf("Montagne", "Forêt", "Prairie", "Sable"), 0, "Sport", Difficulty.MEDIUM, explanation = "Les championnats de VTT se déroulent en montagne car ce terrain accidenté et pentu est idéal pour tester les compétences techniques et l'endurance des cyclistes."),
        Question(13130, "Le rallye automobile se déroule sur routes ouvertes. Vrai ou Faux?", listOf("Vrai", "Faux", "Cela dépend", "Rarement vrai"), 0, "Sport", Difficulty.EASY, explanation = "Le rallye se dispute sur des routes normalement ouvertes à la circulation, mais fermées temporairement pour la course. Les concurrents roulent sur des parcours routiers publics."),
        Question(13131, "En water-polo, est-il autorisé de marcher sur le fond de la piscine?", listOf("Oui", "Non", "Seulement les gardiens", "En première mi-temps seulement"), 1, "Sport", Difficulty.HARD, explanation = "En water-polo, les joueurs ne doivent pas toucher le fond de la piscine, sauf les gardiens dans leur zone. Marcher sur le fond est interdit car le jeu se pratique exclusivement en nageant."),
        Question(13132, "Le biathlon comprend combien de séances de tir par épreuve classique?", listOf("1", "2", "3", "4"), 1, "Sport", Difficulty.MEDIUM, explanation = "Le biathlon classique alterne ski de fond et tir, avec deux séances de tir : une couché et une debout, pour un total de 10 cibles."),
        Question(13133, "En saut à ski, comment appelle-t-on la distance de saut officielle?", listOf("Distance K", "Distance P", "Distance L", "Distance Z"), 0, "Sport", Difficulty.HARD, explanation = "La distance K, ou point K, est le repère sur la piste de réception qui indique la distance de conception du tremplin, servant de référence pour le jugement et le calcul des points."),
        Question(13134, "Le patinage de vitesse court (short-track) se pratique sur quelle longueur de piste?", listOf("300 m", "400 m", "500 m", "1000 m"), 0, "Sport", Difficulty.HARD, explanation = "Le short-track se court sur une piste ovale de 111,12 mètres, et non 300 mètres. La distance de 300 mètres correspond à une épreuve spécifique, mais la piste standard mesure 111,12 m."),
        Question(13135, "En Formule 1, quel constructeur a remporté le plus de titres mondiaux?", listOf("Ferrari", "McLaren", "Mercedes", "Williams"), 2, "Sport", Difficulty.MEDIUM, explanation = "Mercedes détient le record du nombre de titres mondiaux de constructeurs en Formule 1, avec huit championnats remportés consécutivement de 2014 à 2021."),
        Question(13136, "Le curling utilise des pierres de granit. De quel pays proviennent les meilleures?", listOf("Suède", "Écosse", "Canada", "Finlande"), 1, "Sport", Difficulty.HARD, explanation = "Les meilleures pierres de curling proviennent d'Écosse, car le granit d'Ailsa Craig, une île écossaise, est réputé pour sa densité et sa résistance à l'usure."),
        Question(13137, "En motocross, quel obstacle naturel caractérise les circuits?", listOf("Sauts", "Virages", "Boues", "Cailloux"), 0, "Sport", Difficulty.MEDIUM, explanation = "Les circuits de motocross sont conçus sur des terrains accidentés avec des bosses et des dénivelés naturels, ce qui oblige les pilotes à effectuer des sauts pour franchir ces obstacles."),
        Question(13138, "Le pentathlon moderne inclut une épreuve de natation. Quelle distance?", listOf("100 m", "200 m", "300 m", "400 m"), 2, "Sport", Difficulty.HARD, explanation = "L'épreuve de natation du pentathlon moderne est un 200 mètres nage libre, et non 300 mètres. Cette distance a été standardisée pour tester l'endurance et la vitesse des athlètes."),
        Question(13139, "En hockey sur glace, combien de périodes composent un match?", listOf("2", "3", "4", "5"), 1, "Sport", Difficulty.EASY, explanation = "Un match de hockey sur glace se divise en trois périodes de 20 minutes chacune, avec deux pauses de 15 minutes entre elles."),
        Question(13140, "Le skeleton est un sport extrême. Quelle est la position du coureur?", listOf("Debout", "Assis", "À genoux", "Couché face en avant"), 3, "Sport", Difficulty.MEDIUM, explanation = "Le skeleton se pratique sur une piste de glace, allongé sur le ventre, tête en avant, pour optimiser l'aérodynamisme et la vitesse."),
        Question(13141, "En tir à l'arc olympique, quel type de cible est utilisé?", listOf("Cible mobile", "Cible fixe", "Cible électronique", "Cible dynamique"), 1, "Sport", Difficulty.HARD, explanation = "Le tir à l'arc olympique se pratique sur des cibles fixes, avec des distances réglementaires de 70 mètres pour les épreuves de tir sur cible."),
        Question(13142, "Le rallye automobile se différencie de la course par?", listOf("Les vitesses", "Les routes", "Les départs échelonnés", "Les spectateurs"), 2, "Sport", Difficulty.MEDIUM, explanation = "Contrairement aux courses sur circuit où tous les concurrents s'élancent ensemble, le rallye utilise des départs échelonnés pour que chaque équipage parcoure le même itinéraire routier à intervalles réguliers."),
        Question(13143, "En aviron, le barreur utilise quel équipement pour diriger?", listOf("Un gouvernail", "Une rame", "Un cordon", "Une pagaie"), 0, "Sport", Difficulty.HARD, explanation = "Le barreur oriente l'embarcation en actionnant un gouvernail fixé à l'arrière du bateau, via un système de câbles ou une barre."),
        Question(13144, "Le water-polo est un sport collectif aquatique. Depuis quel siècle?", listOf("17e", "18e", "19e", "20e"), 2, "Sport", Difficulty.MEDIUM, explanation = "Le water-polo moderne a été codifié en Grande-Bretagne dans la seconde moitié du XIXe siècle, avec les premières règles écrites en 1870."),
        Question(13145, "En ski de fond, quelle technique n'existe pas?", listOf("Classique", "Skating", "Télémesure", "Libre"), 2, "Sport", Difficulty.HARD, explanation = "Le télémark est une technique de ski alpin, pas de fond. Les techniques de ski de fond sont le pas alternatif, le pas de patineur et le pas de deux temps."),
        Question(13146, "Le biathlon d'hiver comprend quatre types d'épreuves. Laquelle en est une?", listOf("Sprint", "Relais", "Poursuite", "Toutes les réponses"), 3, "Sport", Difficulty.HARD, explanation = "Le biathlon d'hiver comporte quatre épreuves : l'individuel, le sprint, la poursuite et le relais, donc toutes les réponses proposées sont valables."),
        Question(13147, "En luge, combien de courses composent généralement une compétition de Coupe du monde?", listOf("1", "2", "3", "4"), 1, "Sport", Difficulty.HARD, explanation = "En Coupe du monde de luge, chaque épreuve se déroule généralement sur deux manches, dont les temps cumulés déterminent le classement final."),
        Question(13148, "Le saut à ski utilise un tremplin. Quel est son angle approximatif?", listOf("30°", "45°", "60°", "75°"), 1, "Sport", Difficulty.HARD, explanation = "L'angle du tremplin de saut à ski est d'environ 45 degrés, car cet angle permet d'optimiser la portée et la sécurité du sauteur en combinant vitesse et hauteur."),
        Question(13149, "En sports mécaniques, le Dakar est une course mythique. Sur quel continent se déroule-t-elle?", listOf("Afrique", "Asie", "Amérique du Sud", "Europe"), 1, "Sport", Difficulty.MEDIUM, explanation = "Depuis 2009, le Rallye Dakar se dispute en Amérique du Sud puis en Arabie saoudite, située en Asie, pour des raisons de sécurité."),

        // SCIENCE (50 questions) - IDs 13150-13199
        Question(13150, "En optique, qu'est-ce qu'un prisme?", listOf("Un miroir courbe", "Un élément qui réfracte la lumière", "Une lentille convexe", "Un filtre coloré"), 1, "Science", Difficulty.MEDIUM, explanation = "En optique, un prisme est un bloc de verre ou de matière transparente qui dévie la lumière en la réfractant, ce qui permet de séparer ses différentes couleurs."),
        Question(13151, "La réfraction de la lumière se produit en changeant de?", listOf("Température", "Milieu", "Couleur", "Intensité"), 1, "Science", Difficulty.EASY, explanation = "La réfraction se produit lorsque la lumière passe d'un milieu à un autre (comme de l'air à l'eau), ce qui modifie sa vitesse et sa direction."),
        Question(13152, "En acoustique, qu'est-ce que l'amplitude?", listOf("La fréquence", "L'intensité du son", "La longueur d'onde", "La vitesse"), 1, "Science", Difficulty.MEDIUM, explanation = "L'amplitude d'une onde sonore détermine sa puissance, ce qui est perçu par l'oreille comme l'intensité ou le volume du son."),
        Question(13153, "Quel phénomène acoustique provoque l'écho?", listOf("Diffraction", "Réflexion", "Réfraction", "Interférence"), 1, "Science", Difficulty.MEDIUM, explanation = "L'écho est produit par la réflexion des ondes sonores sur une surface dure et lisse, comme un mur ou une falaise, lorsque la distance est suffisante pour que l'oreille distingue le son réfléchi du son original."),
        Question(13154, "La thermodynamique étude l'énergie. Combien de lois principales?", listOf("2", "3", "4", "5"), 2, "Science", Difficulty.HARD, explanation = "La thermodynamique repose sur quatre lois fondamentales : la loi zéro, la première (conservation de l'énergie), la deuxième (entropie) et la troisième (zéro absolu)."),
        Question(13155, "La première loi de la thermodynamique concerne?", listOf("L'entropie", "La conservation de l'énergie", "La température", "La pression"), 1, "Science", Difficulty.HARD, explanation = "Cette loi énonce que l'énergie totale d'un système isolé reste constante, car elle ne peut être ni créée ni détruite, seulement transformée d'une forme à une autre."),
        Question(13156, "En cristallographie, qu'est-ce qu'un cristal?", listOf("Une roche brillante", "Un solide avec structure géométrique ordonnée", "Une molécule", "Un minéral transparent"), 1, "Science", Difficulty.HARD, explanation = "Un cristal se définit par l'arrangement périodique et régulier de ses atomes, ions ou molécules dans l'espace, formant un réseau tridimensionnel ordonné."),
        Question(13157, "Combien de systèmes cristallins existent en cristallographie?", listOf("5", "6", "7", "8"), 2, "Science", Difficulty.HARD, explanation = "En cristallographie, les systèmes cristallins sont au nombre de sept, classés selon les paramètres de leur maille élémentaire (longueurs des axes et angles)."),
        Question(13158, "La biotechnologie utilise les organismes vivants pour créer?", listOf("De l'électricité", "Des médicaments", "De la nourriture", "Toutes les réponses"), 3, "Science", Difficulty.MEDIUM, explanation = "La biotechnologie exploite les processus biologiques des organismes vivants pour développer des produits et solutions dans des domaines variés comme la médecine, l'agriculture et l'industrie."),
        Question(13159, "Qu'est-ce que l'ADN recombinant en biotechnologie?", listOf("ADN naturel", "ADN modifié", "ADN ancien", "ADN synthétique"), 1, "Science", Difficulty.HARD, explanation = "L'ADN recombinant est une molécule d'ADN créée en laboratoire en combinant des séquences de différentes sources, ce qui permet de modifier génétiquement des organismes."),
        Question(13160, "La zoologie étudie les animaux. Combien de phyla principaux?", listOf("10", "20", "30", "Plus de 30"), 3, "Science", Difficulty.HARD, explanation = "Le règne animal est extrêmement diversifié, avec plus de 30 phyla reconnus, incluant des groupes majeurs comme les arthropodes, les mollusques et les chordés."),
        Question(13161, "Quel phylum contient les vertébrés?", listOf("Chordata", "Arthropoda", "Mollusca", "Annelida"), 0, "Science", Difficulty.MEDIUM, explanation = "Les vertébrés appartiennent au phylum des Chordata car ils possèdent tous une notochorde à un stade de leur développement, caractéristique définissant ce groupe."),
        Question(13162, "En optique, quel type de lentille peut corriger la myopie?", listOf("Convexe", "Concave", "Plane", "Biconcave"), 1, "Science", Difficulty.MEDIUM, explanation = "La myopie est corrigée par une lentille concave (divergente) qui écarte les rayons lumineux pour compenser un œil trop long."),
        Question(13163, "L'aberration chromatique est un défaut optique causé par?", listOf("Les impuretés", "La dispersion de la lumière", "Le vieillissement", "La pollution"), 1, "Science", Difficulty.HARD, explanation = "La lumière blanche est composée de différentes couleurs qui ne sont pas toutes déviées de la même manière en traversant une lentille, un phénomène appelé dispersion. Cela provoque des franges colorées sur les bords de l'image."),
        Question(13164, "La vitesse du son dans l'air est approximativement?", listOf("100 m/s", "300 m/s", "340 m/s", "1000 m/s"), 2, "Science", Difficulty.MEDIUM, explanation = "La vitesse du son dans l'air à 20°C au niveau de la mer est d'environ 340 mètres par seconde, car elle dépend de la température et de la densité du milieu."),
        Question(13165, "En acoustique, la fréquence se mesure en?", listOf("Hertz", "Decibels", "Watts", "Pascals"), 0, "Science", Difficulty.EASY, explanation = "Le hertz (Hz) est l'unité de mesure de la fréquence, représentant le nombre d'oscillations par seconde, utilisé en acoustique pour quantifier la hauteur d'un son."),
        Question(13166, "L'effet Doppler modifie la fréquence perçue. Vrai ou Faux?", listOf("Vrai", "Faux", "Partiellement", "Aucune idée"), 0, "Science", Difficulty.MEDIUM, explanation = "L'effet Doppler décrit le changement de fréquence d'une onde (sonore ou lumineuse) lorsque la source et l'observateur sont en mouvement relatif, comme une sirène qui semble plus aiguë en approchant."),
        Question(13167, "La deuxième loi de la thermodynamique concerne?", listOf("L'équilibre", "L'entropie", "La pression", "Le travail"), 1, "Science", Difficulty.HARD, explanation = "Cette loi stipule que l'entropie d'un système isolé ne peut qu'augmenter au cours du temps, définissant ainsi la direction naturelle des processus thermodynamiques."),
        Question(13168, "Quel zéolithe utilisé en industrie vient d'un minéral?", listOf("Synthétique seulement", "Naturel seulement", "Synthétique et naturel", "Pas utilisé"), 2, "Science", Difficulty.HARD, explanation = "Les zéolithes sont des minéraux naturels, mais ils peuvent aussi être synthétisés pour l'industrie, d'où l'existence de deux types : synthétique et naturel."),
        Question(13169, "En biotechnologie, les fermentations produisent?", listOf("De l'oxygène", "De l'alcool", "De l'acide", "Tout cela"), 3, "Science", Difficulty.MEDIUM, explanation = "Les fermentations biotechnologiques peuvent produire des médicaments (comme les antibiotiques), des aliments (yaourt, pain) et des biocarburants (éthanol), selon le microorganisme et les conditions utilisées."),
        Question(13170, "La zoologie range les animaux en?", listOf("Espèces", "Genres", "Familles", "Tous ce qui précède"), 3, "Science", Difficulty.MEDIUM, explanation = "La zoologie classe les animaux selon plusieurs critères : leur habitat, leur mode de reproduction, leur régime alimentaire, et leur structure corporelle. La réponse \"Tous ce qui précède\" est donc correcte car ces catégories sont toutes utilisées."),
        Question(13171, "Quel cristal est utilisé dans les montres?", listOf("Diamant", "Quartz", "Rubis synthétique", "Saphir"), 1, "Science", Difficulty.MEDIUM, explanation = "Le quartz est utilisé dans les montres pour sa piézoélectricité : sous l'effet d'un courant électrique, il vibre à une fréquence très stable, permettant un chronométrage précis."),
        Question(13172, "La polarisation de la lumière crée des ondes?", listOf("Aléatoires", "Oscillant dans une direction", "Multidirectionnelles", "Stationnaires"), 1, "Science", Difficulty.HARD, explanation = "La lumière non polarisée vibre dans toutes les directions, mais la polarisation filtre ces vibrations pour ne conserver qu’un seul plan d’oscillation."),
        Question(13173, "En acoustique, quel matériau absorbe le mieux le son?", listOf("Béton", "Bois", "Mousse poreuse", "Métal"), 2, "Science", Difficulty.MEDIUM, explanation = "La mousse poreuse absorbe le son en piégeant les ondes sonores dans ses cavités, ce qui dissipe leur énergie sous forme de chaleur."),
        Question(13174, "La conductivité thermique mesure?", listOf("La température", "Le flux de chaleur", "L'énergie", "L'expansion"), 1, "Science", Difficulty.HARD, explanation = "La conductivité thermique quantifie la capacité d'un matériau à transmettre la chaleur par conduction, définissant ainsi le flux de chaleur qui le traverse sous un gradient de température."),
        Question(13175, "Les cristaux de glace forment quel système cristallin?", listOf("Cubique", "Hexagonal", "Trigonal", "Monoclinique"), 1, "Science", Difficulty.HARD, explanation = "La glace cristallise dans le système hexagonal en raison de la disposition des molécules d'eau liées par ponts hydrogène, formant une structure en nid d'abeille."),
        Question(13176, "La biotechnologie génétique crée des organismes?", listOf("Fossiles", "Génétiquement modifiés", "Stériles", "Immortels"), 1, "Science", Difficulty.MEDIUM, explanation = "La biotechnologie génétique modifie directement le matériel génétique d'un organisme, créant ainsi des organismes génétiquement modifiés (OGM)."),
        Question(13177, "Quel zoologiste a créé la taxonomie animale?", listOf("Darwin", "Linné", "Cuvier", "Haeckel"), 1, "Science", Difficulty.HARD, explanation = "Carl von Linné, naturaliste suédois du XVIIIe siècle, a établi le système de classification binomiale des espèces, posant les bases de la taxonomie moderne."),
        Question(13178, "La réflexion totale interne se produit avec un angle?", listOf("Aigu", "Critique", "Obtus", "Droit"), 1, "Science", Difficulty.HARD, explanation = "L'angle critique est l'angle d'incidence au-delà duquel la lumière est entièrement réfléchie à l'intérieur d'un milieu transparent, comme dans une fibre optique."),
        Question(13179, "En acoustique, la vélocité du son augmente avec?", listOf("La pression", "La température", "L'humidité", "Le froid"), 1, "Science", Difficulty.HARD, explanation = "Dans un gaz, les molécules se déplacent plus vite quand la température augmente, ce qui accélère la transmission des ondes sonores. Ainsi, la vitesse du son est plus élevée dans l'air chaud que dans l'air froid."),
        Question(13180, "Le zéro absolu en thermodynamique est?", listOf("0°C", "-273,15°C", "-100°C", "Impossible"), 1, "Science", Difficulty.MEDIUM, explanation = "C'est la température la plus basse possible, où l'agitation moléculaire cesse théoriquement. Elle correspond à 0 Kelvin sur l'échelle absolue."),
        Question(13181, "En cristallographie, l'indice de Miller décrit?", listOf("L'orientation des plans", "La dureté", "La couleur", "La transparence"), 0, "Science", Difficulty.HARD, explanation = "Les indices de Miller sont un système de notation utilisé en cristallographie pour définir l'orientation des plans cristallins dans un réseau."),
        Question(13182, "La transgénèse en biotechnologie introduit des gènes?", listOf("D'une autre espèce", "Du même organisme", "Synthétiques", "Fossiles"), 0, "Science", Difficulty.HARD, explanation = "La transgénèse consiste à transférer un gène d'un organisme donneur (d'une autre espèce) vers un organisme receveur, ce qui permet de lui conférer une nouvelle caractéristique."),
        Question(13183, "Les mammifères appartiennent à quel classe zoologique?", listOf("Reptilia", "Aves", "Mammalia", "Amphibia"), 2, "Science", Difficulty.EASY, explanation = "Les mammifères sont classés dans la classe Mammalia en raison de caractéristiques communes comme la présence de glandes mammaires et de poils. Cette classification zoologique regroupe tous les animaux vertébrés qui allaitent leurs petits."),
        Question(13184, "La biréfringence optique apparaît dans les cristaux?", listOf("Isotropes", "Anisotropes", "Opaques", "Amorphes"), 1, "Science", Difficulty.HARD, explanation = "La biréfringence se produit lorsque la lumière traverse un matériau dont les propriétés optiques varient selon la direction, ce qui est le cas des cristaux anisotropes."),
        Question(13185, "L'interférence acoustique provoque?", listOf("Augmentation du volume", "Diminution du volume", "Silence ou renforcement", "Changement de fréquence"), 2, "Science", Difficulty.HARD, explanation = "L'interférence acoustique se produit lorsque deux ondes sonores se rencontrent. Leur combinaison peut créer un silence (interférence destructive) ou un renforcement du son (interférence constructive)."),
        Question(13186, "La capacité thermique spécifique mesure?", listOf("La masse", "L'énergie par unité de masse et température", "Le volume", "La densité"), 1, "Science", Difficulty.HARD, explanation = "La capacité thermique spécifique indique la quantité d'énergie nécessaire pour élever la température d'un kilogramme d'une substance d'un degré Celsius."),
        Question(13187, "Les défauts ponctuels des cristaux incluent?", listOf("Lacunes", "Interstitiels", "Substitutionnels", "Tous ce qui précède"), 3, "Science", Difficulty.HARD, explanation = "Les défauts ponctuels des cristaux regroupent les lacunes, les atomes interstitiels et les atomes substitutionnels, qui sont tous des types de défauts à l'échelle atomique."),
        Question(13188, "La fermentation lactique produit?", listOf("De l'alcool", "De l'acide lactique", "Du gaz carbonique", "De l'eau"), 1, "Science", Difficulty.MEDIUM, explanation = "La fermentation lactique est un processus métabolique qui convertit le sucre en énergie, produisant de l'acide lactique comme sous-produit, notamment dans les muscles lors d'un effort intense ou dans la fabrication du yaourt."),
        Question(13189, "La zoologie marine étudie les créatures de?", listOf("Rivières", "Océans", "Lacs", "Tous les habitats aquatiques"), 1, "Science", Difficulty.MEDIUM, explanation = "La zoologie marine se concentre sur l'étude des animaux vivant dans les milieux marins, principalement les océans, qui couvrent plus de 70% de la surface terrestre."),
        Question(13190, "L'indice de réfraction compare les vitesses de lumière en?", listOf("Deux milieux", "Vide et milieu", "Lumière et matière", "Deux ondes"), 1, "Science", Difficulty.HARD, explanation = "L'indice de réfraction d'un milieu est le rapport entre la vitesse de la lumière dans le vide et sa vitesse dans ce milieu."),
        Question(13191, "La diffraction se produit quand une onde rencontre un?", listOf("Obstacle", "Miroir", "Prisme", "Filtre"), 0, "Science", Difficulty.MEDIUM, explanation = "La diffraction est le phénomène de déviation des ondes lorsqu'elles rencontrent un obstacle ou une ouverture, ce qui modifie leur propagation."),
        Question(13192, "En thermodynamique, le travail est lié à?", listOf("La chaleur", "La pression et le volume", "La température", "L'entropie"), 1, "Science", Difficulty.HARD, explanation = "En thermodynamique, le travail mécanique est défini comme le produit de la pression extérieure par la variation de volume, selon la formule W = -PΔV."),
        Question(13193, "La structure cristalline se répète selon un?", listOf("Motif aléatoire", "Réseau périodique", "Gradient", "Chaos"), 1, "Science", Difficulty.HARD, explanation = "Un réseau périodique décrit la répétition régulière et tridimensionnelle des motifs atomiques dans un cristal, définissant ainsi sa structure ordonnée."),
        Question(13194, "La sélection génétique en biotechnologie favorise les?", listOf("Mutation", "Traits souhaités", "Diversité", "Aléatoire"), 1, "Science", Difficulty.MEDIUM, explanation = "En biotechnologie, la sélection génétique consiste à choisir et propager des organismes possédant des caractéristiques avantageuses, comme la résistance aux maladies ou un rendement accru."),
        Question(13195, "La zoologie comportementale étudie le?", listOf("Squelette", "Comportement animal", "L'ADN", "La nutrition"), 1, "Science", Difficulty.MEDIUM, explanation = "La zoologie comportementale, aussi appelée éthologie, se concentre sur l'observation et l'analyse des actions et réactions des animaux dans leur environnement naturel."),
        Question(13196, "L'extinction des couleurs optiques se voit avec la lumière?", listOf("Blanche", "Polarisée", "Monochromatique", "Infrarouge"), 1, "Science", Difficulty.HARD, explanation = "La lumière polarisée vibre dans un seul plan, ce qui permet de filtrer les reflets et de révéler les couleurs optiques, contrairement à la lumière non polarisée."),
        Question(13197, "La résonance acoustique amplifie les sons à certaines?", listOf("Couleurs", "Fréquences", "Amplitudes", "Positions"), 1, "Science", Difficulty.HARD, explanation = "La résonance acoustique se produit lorsqu'un objet vibre à sa fréquence naturelle, ce qui amplifie les ondes sonores à des fréquences spécifiques."),
        Question(13198, "La conductivité thermique des métaux vient des électrons?", listOf("Fixes", "Libres", "Liés", "Immobiles"), 1, "Science", Difficulty.HARD, explanation = "Les électrons libres dans les métaux permettent une transmission rapide de l'énergie thermique, ce qui explique leur haute conductivité thermique."),
        Question(13199, "Les chaînes polypeptidiques en biotechnologie forment les?", listOf("Acides nucléiques", "Protéines", "Lipides", "Glucides"), 1, "Science", Difficulty.MEDIUM, explanation = "Les chaînes polypeptidiques sont des séquences d'acides aminés qui, une fois repliées et assemblées, constituent les protéines, essentielles à la structure et au fonctionnement des cellules."),

        // HISTOIRE (50 questions) - IDs 13200-13249
        Question(13200, "L'Empire ottoman s'est établi au?", listOf("12e siècle", "13e siècle", "14e siècle", "15e siècle"), 2, "Histoire", Difficulty.MEDIUM, explanation = "L'Empire ottoman a été fondé vers 1299 par Osman Ier, ce qui le place au tournant du 14e siècle. Il a connu son essor initial durant ce siècle en Anatolie."),
        Question(13201, "Quel empire a conquis une grande partie de l'Asie au 13e siècle?", listOf("Ottoman", "Mongol", "Byzantin", "Perse"), 1, "Histoire", Difficulty.MEDIUM, explanation = "L'Empire mongol, sous la direction de Gengis Khan puis de ses successeurs, a étendu sa domination sur une vaste partie de l'Asie au 13e siècle, devenant le plus grand empire contigu de l'histoire."),
        Question(13202, "Genghis Khan fondateur de l'Empire mongol était?", listOf("Chinois", "Mongol", "Persan", "Turc"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Genghis Khan est né dans une tribu mongole et a unifié les clans nomades de la région pour fonder l'Empire mongol au début du XIIIe siècle."),
        Question(13203, "La capitale historique de l'Empire ottoman était?", listOf("Ankara", "Constantinople", "Damas", "Le Caire"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Constantinople, prise par les Ottomans en 1453, devint leur capitale jusqu’à la chute de l’empire en 1922."),
        Question(13204, "Le Japon féodal était gouverné par les?", listOf("Emirs", "Sultans", "Shoguns", "Khans"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Au Japon féodal, l'empereur détenait un rôle symbolique tandis que le pouvoir militaire et politique était exercé par les shoguns, des chefs militaires héréditaires."),
        Question(13205, "La période Edo du Japon a duré combien de siècles?", listOf("1", "2", "3", "4"), 1, "Histoire", Difficulty.HARD, explanation = "La période Edo, marquée par le shogunat Tokugawa, a débuté en 1603 et s'est achevée en 1868, soit une durée d'environ deux siècles et demi."),
        Question(13206, "L'Empire byzantin était la continuation de quel empire?", listOf("Romain", "Perse", "Grec", "Ottoman"), 0, "Histoire", Difficulty.MEDIUM, explanation = "L'Empire byzantin est issu de la division de l'Empire romain en 395, avec sa capitale à Constantinople. Il a conservé les institutions et la culture romaines jusqu'à sa chute en 1453."),
        Question(13207, "Constantinople tombée en 1453 marqua la fin de?", listOf("L'Empire ottoman", "L'Empire byzantin", "L'Empire mongol", "L'Empire romain"), 1, "Histoire", Difficulty.MEDIUM, explanation = "La chute de Constantinople en 1453, après le siège mené par les Ottomans, mit fin à l'Empire byzantin, dernier vestige de l'Empire romain d'Orient."),
        Question(13208, "Quel traité en 1648 termina la guerre de Trente Ans?", listOf("Westphalie", "Utrecht", "Nimègue", "Osnabrück"), 0, "Histoire", Difficulty.HARD, explanation = "Les traités de Westphalie, signés en 1648, mirent fin à la guerre de Trente Ans en Europe, établissant un nouvel ordre politique basé sur la souveraineté des États."),
        Question(13209, "La Déclaration d'indépendance américaine date de?", listOf("1775", "1776", "1777", "1778"), 1, "Histoire", Difficulty.EASY, explanation = "Adoptée le 4 juillet 1776 par le Congrès continental, elle proclame la séparation des treize colonies britanniques et la naissance des États-Unis."),
        Question(13210, "Qui a signé principalement la Déclaration d'indépendance américaine?", listOf("George Washington", "Benjamin Franklin", "Thomas Jefferson", "Adams"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Thomas Jefferson, alors délégué de la Virginie, fut le principal rédacteur du texte de la Déclaration d'indépendance, adoptée le 4 juillet 1776."),
        Question(13211, "Les Croisades étaient dirigées contre le pouvoir?", listOf("Ottoman", "Mongol", "Arabe", "Perse"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Les Croisades étaient des expéditions militaires chrétiennes visant à reprendre Jérusalem et d'autres lieux saints, alors sous contrôle musulman, principalement dirigé par les Arabes."),
        Question(13212, "La première Croisade débuta en?", listOf("1095", "1096", "1097", "1098"), 0, "Histoire", Difficulty.HARD, explanation = "L'appel à la croisade fut lancé par le pape Urbain II lors du concile de Clermont en novembre 1095."),
        Question(13213, "Quelle Croisade reprit Jérusalem en 1187?", listOf("Deuxième", "Troisième", "Quatrième", "Cinquième"), 1, "Histoire", Difficulty.HARD, explanation = "La troisième croisade (1189-1192) fut lancée après la prise de Jérusalem par Saladin en 1187, mais elle échoua à reprendre la ville."),
        Question(13214, "L'Empire mongol s'effondra finalement au?", listOf("14e siècle", "15e siècle", "16e siècle", "17e siècle"), 1, "Histoire", Difficulty.HARD, explanation = "L'Empire mongol, après son apogée au 13e siècle, se fragmenta en plusieurs khanats rivaux qui déclinèrent progressivement, et la dernière entité mongole unifiée, la dynastie Yuan en Chine, tomba en 1368, marquant la fin effective de l'empire au début du 15e siècle."),
        Question(13215, "Le Bushido était le code des?", listOf("Guerriers ottomans", "Samourais japonais", "Chevaliers croisés", "Guerriers mongols"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Le Bushido, signifiant la voie du guerrier, était le code moral et éthique suivi par les samouraïs au Japon féodal."),
        Question(13216, "La Grande Mosquée bleue fut construite à?", listOf("Damas", "Istanbul", "Le Caire", "Bagdad"), 1, "Histoire", Difficulty.HARD, explanation = "La mosquée bleue, ou Sultanahmet, fut construite à Istanbul sous le règne d'Ahmed Ier, entre 1609 et 1616."),
        Question(13217, "Quel empire contrôlait le détroit de Bosphore au 15e siècle?", listOf("Byzance", "Ottoman", "Génois", "Vénitien"), 1, "Histoire", Difficulty.HARD, explanation = "L'Empire ottoman a conquis Constantinople en 1453, prenant ainsi le contrôle du détroit de Bosphore, une voie stratégique entre l'Europe et l'Asie."),
        Question(13218, "La dynastie Ming en Chine succéda à?", listOf("Yuan", "Song", "Tang", "Han"), 0, "Histoire", Difficulty.HARD, explanation = "La dynastie Ming a renversé la dynastie Yuan, d'origine mongole, fondée par Kubilai Khan, mettant fin à la domination mongole sur la Chine."),
        Question(13219, "Les samourais disparurent en tant que classe au?", listOf("17e siècle", "18e siècle", "19e siècle", "20e siècle"), 2, "Histoire", Difficulty.HARD, explanation = "La restauration de Meiji en 1868 abolit le système féodal et les privilèges des samouraïs, mettant fin à leur existence en tant que classe sociale distincte au 19e siècle."),
        Question(13220, "Quelle ville fut le siège principal de l'Empire byzantin?", listOf("Athènes", "Constantinople", "Rome", "Ankara"), 1, "Histoire", Difficulty.EASY, explanation = "Constantinople, fondée par Constantin Ier en 330, fut la capitale de l'Empire byzantin jusqu'à sa chute en 1453, servant de centre politique, économique et religieux."),
        Question(13221, "Le code de Hammurabi appartenait à quel peuple?", listOf("Égyptiens", "Babyloniens", "Perses", "Hindous"), 1, "Histoire", Difficulty.HARD, explanation = "Hammurabi était le sixième roi de la première dynastie babylonienne, et son code de lois est l'un des plus anciens ensembles juridiques connus, rédigé en akkadien vers 1750 av. J.-C."),
        Question(13222, "Les croisades ont duré approximativement?", listOf("100 ans", "150 ans", "200 ans", "300 ans"), 2, "Histoire", Difficulty.HARD, explanation = "La première croisade a été lancée en 1096 et la dernière grande expédition, la neuvième croisade, s'est achevée en 1272, soit une période d'environ 200 ans."),
        Question(13223, "Quel était le prétexte principal des Croisades?", listOf("Expansion commerciale", "Récupérer la Terre Sainte", "Colonisation", "Exploration"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Les Croisades étaient des expéditions militaires lancées par les chrétiens d'Occident à partir de 1095, officiellement pour reprendre Jérusalem et les lieux saints aux musulmans."),
        Question(13224, "L'indépendance des États-Unis causa une rupture avec?", listOf("La Francce", "L'Espagne", "L'Angleterre", "La Hollande"), 2, "Histoire", Difficulty.EASY, explanation = "La guerre d'indépendance américaine (1775-1783) opposa les Treize colonies à leur métropole, le Royaume de Grande-Bretagne, menant à la rupture officielle avec l'Angleterre."),
        Question(13225, "Marco Polo voyagea en Chine durant l'Empire?", listOf("Ming", "Tang", "Yuan", "Song"), 2, "Histoire", Difficulty.HARD, explanation = "Marco Polo atteignit la Chine sous la dynastie mongole des Yuan, fondée par Kubilai Khan, petit-fils de Gengis Khan."),
        Question(13226, "La chute de Constantinople en 1453 marqua le début du déclin de?", listOf("Byzance", "Rome", "La Perse", "La Grèce"), 0, "Histoire", Difficulty.MEDIUM, explanation = "La prise de Constantinople par les Ottomans en 1453 mit fin à l'Empire byzantin, entamant son déclin définitif après des siècles de rétrécissement territorial."),
        Question(13227, "Quel traité reconnut l'indépendance américaine?", listOf("Traité de Paris 1763", "Traité de Paris 1783", "Traité de Versailles", "Traité de Westphalie"), 1, "Histoire", Difficulty.HARD, explanation = "Le traité de Paris de 1783 mit fin à la guerre d'indépendance américaine, officialisant la reconnaissance de la souveraineté des États-Unis par la Grande-Bretagne."),
        Question(13228, "Le Japon féodal était divisé entre plusieurs?", listOf("Rois", "Daimyo", "Empereurs", "Patriarches"), 1, "Histoire", Difficulty.HARD, explanation = "Le Japon féodal était divisé en plusieurs fiefs gouvernés par des seigneurs locaux appelés daimyo, qui détenaient un pouvoir militaire et économique important."),
        Question(13229, "Qui a unifiée le Japon à la fin du 16e siècle?", listOf("Tokugawa", "Oda Nobunaga", "Toyotomi", "Ashikaga"), 1, "Histoire", Difficulty.HARD, explanation = "Oda Nobunaga a amorcé l'unification du Japon en brisant le pouvoir des seigneurs de la guerre féodaux, mais c'est son successeur Toyotomi Hideyoshi qui l'a achevée."),
        Question(13230, "La Pax Romana était l'époque de paix en?", listOf("Empire byzantin", "Empire ottoman", "Empire romain", "Empire mongol"), 2, "Histoire", Difficulty.MEDIUM, explanation = "La Pax Romana désigne la longue période de stabilité et de prospérité imposée par l'Empire romain dans le bassin méditerranéen, principalement sous le règne d'Auguste et de ses successeurs."),
        Question(13231, "Quel philosophe grec influença les croisades?", listOf("Platon", "Aristote", "Socrate", "Les Pères de l'Église"), 3, "Histoire", Difficulty.HARD, explanation = "Les Pères de l'Église, comme saint Augustin, ont théorisé la guerre juste, ce qui a influencé la justification religieuse des croisades."),
        Question(13232, "L'Empire des Hasmonéens relevait de la région?", listOf("Égypte", "Mésopotamie", "Judée", "Syrie"), 2, "Histoire", Difficulty.HARD, explanation = "Les Hasmonéens ont dirigé un royaume indépendant en Judée après la révolte des Maccabées contre l'Empire séleucide, au IIe siècle avant J.-C."),
        Question(13233, "Qui était Saladin lors des Croisades?", listOf("Un croisé", "Un leader musulman", "Un pape", "Un chevalier"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Saladin, de son vrai nom Salah al-Din, fut le sultan d'Égypte et de Syrie qui unifia les forces musulmanes et reprit Jérusalem aux croisés en 1187."),
        Question(13234, "La période Heian au Japon correspondait à l'époque du?", listOf("Moyen Âge en Europe", "Renaissance", "Antiquité tardive", "Époque moderne"), 0, "Histoire", Difficulty.HARD, explanation = "La période Heian (794-1185) correspond à l'apogée de la cour impériale japonaise, contemporaine du Moyen Âge européen (Ve-XVe siècle)."),
        Question(13235, "Le Shogunat Tokugawa dura?", listOf("100 ans", "150 ans", "250 ans", "300 ans"), 2, "Histoire", Difficulty.HARD, explanation = "Le shogunat Tokugawa, fondé en 1603 par Tokugawa Ieyasu, maintint une paix et un isolement du Japon jusqu'à sa chute en 1868, soit environ 250 ans."),
        Question(13236, "Constantinople était aussi appelée?", listOf("Byzance", "Ankara", "Damas", "Jérusalem"), 0, "Histoire", Difficulty.EASY, explanation = "Constantinople fut fondée sur le site de l'ancienne cité grecque de Byzance, fondée vers 660 av. J.-C."),
        Question(13237, "L'armée janissaire servait l'Empire?", listOf("Byzantin", "Ottoman", "Mongol", "Perse"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Les janissaires formaient l'élite de l'infanterie de l'Empire ottoman, recrutés initialement via le système du devchirmé."),
        Question(13238, "Qui fut le premier Président des États-Unis?", listOf("Thomas Jefferson", "George Washington", "Benjamin Franklin", "John Adams"), 1, "Histoire", Difficulty.EASY, explanation = "George Washington fut le premier président des États-Unis, élu en 1789 après avoir dirigé l'armée continentale durant la guerre d'indépendance et présidé la Convention constitutionnelle."),
        Question(13239, "La Grande Muraille de Chine défendait contre?", listOf("Les Mongols", "Les Arabes", "Les Européens", "Les Indiens"), 0, "Histoire", Difficulty.MEDIUM, explanation = "La Grande Muraille a été principalement construite et renforcée sous la dynastie Ming pour se protéger des invasions mongoles venues du nord."),
        Question(13240, "Quel est le plus ancien texte connu du Japon?", listOf("Kojiki", "Nihon Shoki", "Man'yōshū", "Ise Monogatari"), 0, "Histoire", Difficulty.HARD, explanation = "Le Kojiki, achevé en 712, est le plus ancien recueil de mythes, légendes et chroniques historiques du Japon, compilé sur ordre de l'impératrice Gemmei."),
        Question(13241, "L'Inquisition espagnole poursuivait quels groupes?", listOf("Hérétiques", "Juifs et musulmans", "Protestants", "Tous les précédents"), 3, "Histoire", Difficulty.HARD, explanation = "L'Inquisition espagnole visait initialement les juifs convertis soupçonnés de crypto-judaïsme, puis s'est étendue aux musulmans convertis, aux protestants et à d'autres hérétiques, ainsi qu'aux blasphémateurs et sorciers."),
        Question(13242, "L'impact des Croisades inclut?", listOf("Échanges commerciaux", "Conflits religieux", "Avancées culturelles", "Tout ce qui précède"), 3, "Histoire", Difficulty.HARD, explanation = "Les Croisades ont eu des conséquences multiples et durables : échanges culturels et commerciaux entre Orient et Occident, affaiblissement de l'Empire byzantin, et montée de la méfiance entre chrétiens et musulmans."),
        Question(13243, "Quel sultan ottoman conquit Constantinople?", listOf("Murad II", "Mehmed II", "Sélim I", "Süleyman"), 1, "Histoire", Difficulty.HARD, explanation = "Mehmed II, dit le Conquérant, prit Constantinople en 1453, mettant fin à l'Empire byzantin et faisant de la ville la nouvelle capitale ottomane."),
        Question(13244, "La chute de l'Empire mongol en Chine conduisit à?", listOf("La dynastie Ming", "La dynastie Qing", "La dynastie Yuan", "La dynastie Han"), 0, "Histoire", Difficulty.HARD, explanation = "La chute de la dynastie mongole des Yuan en 1368 permit à Zhu Yuanzhang de fonder la dynastie Ming, qui rétablit le pouvoir chinois Han."),
        Question(13245, "Les samouraïs servaient quel seigneur au Japon féodal?", listOf("Le Shogun", "Le Daimyo", "L'Empereur", "Le Dairi"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Au Japon féodal, les samouraïs étaient au service d'un daimyo, un puissant seigneur terrien, en échange de terres et de protection."),
        Question(13246, "La Réforme protestante débuta par?", listOf("Wycliffe", "Hus", "Luther", "Calvin"), 2, "Histoire", Difficulty.HARD, explanation = "En 1517, Martin Luther publie ses 95 thèses contre les indulgences, acte fondateur de la Réforme protestante."),
        Question(13247, "Le Suez fut creusé pour relier?", listOf("Méditerranée et Mer Rouge", "Rhin et Danube", "Mer Noire et Mer Caspienne", "Manche et Atlantique"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Le canal de Suez, inauguré en 1869, relie la mer Méditerranée à la mer Rouge, offrant une route maritime directe entre l'Europe et l'Asie sans contourner l'Afrique."),
        Question(13248, "Le massacre de la Barthélemy impliqua?", listOf("Catholiques et protestants", "Musulmans et chrétiens", "Juifs et chrétiens", "Hérétiques et papistes"), 0, "Histoire", Difficulty.HARD, explanation = "Le massacre de la Saint-Barthélemy, en 1572, fut une tuerie de protestants (huguenots) ordonnée par les catholiques à Paris, puis dans toute la France."),
        Question(13249, "Lequel de ces empires n'a PAS été mentionné ici?", listOf("Égyptien", "Ottoman", "Byzantin", "Mongol"), 0, "Histoire", Difficulty.EASY, explanation = "L'empire égyptien n'a pas été mentionné dans le quiz, contrairement aux autres empires cités dans la question."),

        // GÉOGRAPHIE (50 questions) - IDs 13250-13299
        Question(13250, "Le Pôle Nord géographique se situe à?", listOf("45°N", "60°N", "75°N", "90°N"), 3, "Géographie", Difficulty.EASY, explanation = "Le Pôle Nord géographique est le point le plus septentrional de la Terre, situé à l'intersection de l'axe de rotation terrestre avec la surface, ce qui correspond à la latitude 90° Nord."),
        Question(13251, "L'Antarctique est un continent. Vrai ou Faux?", listOf("Vrai", "Faux", "Partiellement", "Débattu"), 0, "Géographie", Difficulty.EASY, explanation = "L'Antarctique est bien un continent, le cinquième par sa superficie, recouvert de glace et entouré par l'océan Austral. Il se distingue de l'Arctique, qui est une banquise."),
        Question(13252, "Quel est l'océan qui entoure l'Antarctique?", listOf("Atlantique", "Indien", "Océan Glacial Austral", "Pacifique"), 2, "Géographie", Difficulty.MEDIUM, explanation = "L'océan Glacial Austral est le nom officiel donné à la masse d'eau entourant le continent Antarctique, reconnu comme le quatrième plus grand océan du monde."),
        Question(13253, "L'archipel de la Polynésie compte combien d'îles aproximativement?", listOf("100", "300", "1000", "3000"), 3, "Géographie", Difficulty.HARD, explanation = "La Polynésie est un vaste ensemble d'îles dispersées dans l'océan Pacifique, comprenant environ 3000 îles et atolls, dont les plus connus sont Tahiti, Bora Bora et les Marquises."),
        Question(13254, "Le détroit de Gibraltar sépare l'Europe et l'?", listOf("Asie", "Afrique", "Océanie", "Amérique"), 1, "Géographie", Difficulty.EASY, explanation = "Le détroit de Gibraltar relie la mer Méditerranée à l'océan Atlantique et constitue la frontière naturelle entre le continent européen (Espagne) et le continent africain (Maroc)."),
        Question(13255, "Le Cap Horn est le point sud de quel continent?", listOf("Australie", "Afrique", "Amérique du Sud", "Antarctique"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le Cap Horn se situe à l'extrémité de l'archipel de la Terre de Feu, au sud du Chili, ce qui en fait le point le plus méridional de l'Amérique du Sud."),
        Question(13256, "Le golfe Persique sépare l'Iran de la?", listOf("Mer Rouge", "Péninsule arabique", "Mer Caspienne", "Mer d'Oman"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le golfe Persique est bordé au sud-ouest par la péninsule arabique, qui regroupe l'Arabie saoudite, le Yémen, Oman et d'autres pays."),
        Question(13257, "La baie de Hudson est située au?", listOf("Canada", "Sibérie", "Groenland", "Alaska"), 0, "Géographie", Difficulty.MEDIUM, explanation = "La baie d'Hudson est une grande mer intérieure située dans le nord-est du Canada, bordée par les provinces du Manitoba, de l'Ontario et du Québec."),
        Question(13258, "L'Islande est-elle un archipel ou une seule île?", listOf("Archipel", "Une seule île", "Deux îles", "Cela dépend"), 0, "Géographie", Difficulty.MEDIUM, explanation = "L'Islande est un archipel car elle est entourée de nombreuses petites îles, comme les îles Vestmann, en plus de l'île principale."),
        Question(13259, "Les Îles Féroé appartiennent à quel pays?", listOf("Islande", "Danemark", "Suède", "Norvège"), 1, "Géographie", Difficulty.HARD, explanation = "Les Îles Féroé sont un territoire autonome du Royaume du Danemark depuis 1948, tout en conservant leur propre gouvernement et leur drapeau."),
        Question(13260, "Le détroit de Béring sépare la Russie de?", listOf("Canada", "Alaska", "Groenland", "Islande"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le détroit de Béring sépare la Russie de l'Alaska, qui est un État des États-Unis."),
        Question(13261, "Le golfe du Mexique est bordé par?", listOf("États-Unis uniquement", "États-Unis et Mexique", "États-Unis, Mexique et Cuba", "États-Unis, Mexique et Canada"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le golfe du Mexique est bordé au nord par les États-Unis, à l'ouest et au sud par le Mexique, et au sud-est par l'île de Cuba."),
        Question(13262, "La baie de la Thaïlande borde la côte de?", listOf("Malaisie", "Thaïlande", "Cambodge", "Tous les trois"), 3, "Géographie", Difficulty.HARD, explanation = "La baie de Thaïlande est bordée par la Thaïlande, le Cambodge et le Vietnam, ces trois pays partageant son littoral."),
        Question(13263, "Le cap de Bonne-Espérance est en?", listOf("Angola", "Afrique du Sud", "Namibie", "Mozambique"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le cap de Bonne-Espérance est situé à l'extrémité sud-ouest de l'Afrique, dans la province du Cap-Occidental en Afrique du Sud."),
        Question(13264, "L'archipel de Galápagos appartient à?", listOf("Pérou", "Chili", "Équateur", "Colombie"), 2, "Géographie", Difficulty.MEDIUM, explanation = "L'archipel des Galápagos est situé dans l'océan Pacifique, à environ 1 000 kilomètres des côtes de l'Équateur, pays auquel il appartient politiquement depuis 1832."),
        Question(13265, "La mer du Nord est entourée par?", listOf("France et Angleterre", "Scandinavie et Angleterre", "Allemagne et Danemark", "Tous les précédents"), 3, "Géographie", Difficulty.HARD, explanation = "La mer du Nord borde le Royaume-Uni, la Norvège, le Danemark, l'Allemagne, les Pays-Bas, la Belgique et la France, donc toutes ces réponses sont correctes."),
        Question(13266, "Le détroit de Malacca relie quel océan à quel océan?", listOf("Atlantique-Pacifique", "Indien-Pacifique", "Atlantique-Indien", "Arctique-Atlantique"), 1, "Géographie", Difficulty.HARD, explanation = "Le détroit de Malacca est une voie maritime clé entre l'océan Indien et l'océan Pacifique, située entre la péninsule Malaise et l'île indonésienne de Sumatra."),
        Question(13267, "L'île de Madagascar appartient à quel pays?", listOf("Afrique du Sud", "Mozambique", "Madagascar", "C'est un état indépendant"), 3, "Géographie", Difficulty.MEDIUM, explanation = "Madagascar est un État souverain depuis son indépendance de la France en 1960, et ne fait partie d'aucun autre pays."),
        Question(13268, "Le golfe d'Aden borde qui?", listOf("Arabie Saoudite et Somalie", "Yémen et Somalie", "Érythrée et Djibouti", "Tous les précédents"), 1, "Géographie", Difficulty.HARD, explanation = "Le golfe d'Aden sépare la corne de l'Afrique de la péninsule arabique, avec le Yémen au nord et la Somalie au sud."),
        Question(13269, "Le détroit du Bosphore relie quel deux mers?", listOf("Adriatique-Égée", "Noire-Méditerranée", "Noire-Marmara", "Marmara-Égée"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le détroit du Bosphore relie la mer Noire à la mer de Marmara, séparant l'Europe de l'Asie et traversant Istanbul."),
        Question(13270, "L'archipel des Malouines appartient à?", listOf("Argentine", "Royaume-Uni", "Chili", "Débattu"), 1, "Géographie", Difficulty.HARD, explanation = "Les îles Malouines sont un territoire britannique d'outre-mer, bien que l'Argentine en revendique la souveraineté."),
        Question(13271, "Le cap Nord est le point nord de la Scandinavie. Vrai ou Faux?", listOf("Vrai", "Faux", "Partiellement", "Débattu"), 0, "Géographie", Difficulty.HARD, explanation = "Le cap Nord, situé sur l'île de Magerøya en Norvège, est généralement considéré comme le point le plus septentrional de la Scandinavie accessible au public."),
        Question(13272, "La Terre de Feu est partagée entre la Patagonie et?", listOf("L'Uruguay", "Le Chili", "L'Argentine", "Les Malouines"), 2, "Géographie", Difficulty.HARD, explanation = "La Terre de Feu est un archipel situé à l'extrémité sud de l'Amérique du Sud, partagé entre le Chili et l'Argentine. La Patagonie est une région qui s'étend sur ces deux pays, mais la question oppose la Patagonie à l'Argentine pour désigner l'autre partie du territoire."),
        Question(13273, "L'île de Bornéo est partagée par combien de pays?", listOf("2", "3", "4", "5"), 1, "Géographie", Difficulty.HARD, explanation = "Bornéo est partagée entre l'Indonésie, la Malaisie et le Brunei."),
        Question(13274, "Le détroit de Kerch sépare la Russie de?", listOf("Géorgie", "Crimée", "Ukraine", "Turquie"), 2, "Géographie", Difficulty.HARD, explanation = "Le détroit de Kerch relie la mer Noire à la mer d'Azov et sépare la péninsule de Crimée (annexée par la Russie) de la Russie continentale, avec l'Ukraine située à l'ouest."),
        Question(13275, "L'Afrique du Nord inclut le cap de Bonne-Espérance. Vrai ou Faux?", listOf("Vrai", "Faux", "Partiellement", "Débattu"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le cap de Bonne-Espérance se situe à l'extrémité sud-ouest de l'Afrique du Sud, en Afrique australe, bien loin de l'Afrique du Nord qui englobe des pays comme le Maroc ou l'Algérie."),
        Question(13276, "L'archipel de la Micronésie est composé de combien d'îles?", listOf("Centaines", "Milliers", "Dizaines", "Centaine"), 1, "Géographie", Difficulty.HARD, explanation = "La Micronésie est une région du Pacifique comptant plus de 2 000 îles, souvent dispersées en petits atolls et archipels."),
        Question(13277, "Le golfe du Saint-Laurent est au?", listOf("Québec", "Canada atlantique", "Terre-Neuve", "Nouvelle-Écosse"), 1, "Géographie", Difficulty.HARD, explanation = "Le golfe du Saint-Laurent baigne les provinces du Nouveau-Brunswick, de la Nouvelle-Écosse, de l'Île-du-Prince-Édouard et de Terre-Neuve-et-Labrador, qui forment la région du Canada atlantique."),
        Question(13278, "L'île de Nouvelle-Zélande comporte combien d'îles principales?", listOf("1", "2", "3", "4"), 1, "Géographie", Difficulty.MEDIUM, explanation = "La Nouvelle-Zélande est composée de deux îles principales : l'île du Nord et l'île du Sud, séparées par le détroit de Cook."),
        Question(13279, "Le cap York est le point nord de l'?", listOf("Australie", "Afrique", "Amérique du Sud", "Nouvelle-Zélande"), 0, "Géographie", Difficulty.HARD, explanation = "Le cap York est situé à l'extrémité nord de la péninsule du cap York, dans l'État du Queensland, en Australie."),
        Question(13280, "L'océan Arctique est glacé. Combien de pays riverains?", listOf("4", "5", "6", "7"), 3, "Géographie", Difficulty.HARD, explanation = "Les cinq pays riverains de l'océan Arctique sont le Canada, le Danemark (via le Groenland), la Norvège, la Russie et les États-Unis."),
        Question(13281, "Les îles Åland appartiennent à?", listOf("Suède", "Finlande", "Norvège", "Danemark"), 1, "Géographie", Difficulty.HARD, explanation = "L'archipel d'Åland est une région autonome et démilitarisée de la Finlande, avec une population majoritairement suédophone."),
        Question(13282, "Le détroit de Tartaria existe-t-il?", listOf("Oui", "Non", "Historiquement", "C'est un mythe"), 3, "Géographie", Difficulty.HARD, explanation = "Le détroit de Tartarie est une invention cartographique apparue sur certaines cartes du XVIe au XVIIIe siècle, censée séparer l'Asie de l'Amérique du Nord, mais il n'a jamais existé dans la réalité."),
        Question(13283, "L'île de Ceylan s'appelle maintenant?", listOf("Chypre", "Sri Lanka", "Taïwan", "Maldives"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Ceylan a été renommé Sri Lanka en 1972, après son indépendance du Royaume-Uni, pour refléter son héritage culturel local."),
        Question(13284, "Le golfe du Tonkin borde quel pays?", listOf("Thaïlande", "Laos", "Viêt-Nam", "Cambodge"), 2, "Géographie", Difficulty.HARD, explanation = "Le golfe du Tonkin est situé au large des côtes du nord du Viêt-Nam, ainsi que de la Chine. Il tire son nom de la région historique du Tonkin, qui correspond au nord du Viêt-Nam actuel."),
        Question(13285, "L'archipel de Zanzibar appartient à?", listOf("Kenya", "Tanzanie", "Mozambique", "Madagascar"), 1, "Géographie", Difficulty.HARD, explanation = "Zanzibar est un archipel semi-autonome qui fait partie de la République unie de Tanzanie depuis 1964, après la fusion du Tanganyika et de Zanzibar."),
        Question(13286, "Le cap Agulhas est le point sud-est de l'?", listOf("Afrique du Sud", "Afrique", "Madagascar", "Océan Indien"), 0, "Géographie", Difficulty.HARD, explanation = "Le cap Agulhas est le point le plus méridional du continent africain, situé en Afrique du Sud, où les océans Atlantique et Indien se rencontrent officiellement."),
        Question(13287, "Les îles Maldives sont composées de combien d'îles?", listOf("100", "500", "1000", "2000"), 3, "Géographie", Difficulty.HARD, explanation = "Les Maldives sont un archipel de l'océan Indien comprenant environ 1 200 îles, regroupées en 26 atolls. Le nombre de 2 000 est souvent cité en incluant les îlots et bancs de sable."),
        Question(13288, "Le détroit de Tiran sépare l'Égypte et?", listOf("Arabie Saoudite", "Israël", "Jordanie", "Liban"), 0, "Géographie", Difficulty.HARD, explanation = "Le détroit de Tiran, situé à l'entrée du golfe d'Aqaba, sépare la péninsule du Sinaï égyptienne de la côte nord-ouest de l'Arabie Saoudite."),
        Question(13289, "L'archipel de la Sonde inclut Sumatra et?", listOf("Bornéo", "Sulawesi", "Java", "Tous les précédents"), 3, "Géographie", Difficulty.HARD, explanation = "L'archipel de la Sonde comprend les grandes îles de Sumatra, Java, Bornéo, Sulawesi et Timor, ainsi que des milliers d'îles plus petites, donc toutes les options proposées en font partie."),
        Question(13290, "Le cap Lizard est le point sud-est de?", listOf("Irlande", "Cornouailles anglaise", "Pays de Galles", "Écosse"), 1, "Géographie", Difficulty.HARD, explanation = "Le cap Lizard marque l'extrémité sud-est de la péninsule de Cornouailles, en Angleterre, et constitue le point le plus méridional de l'île de Grande-Bretagne."),
        Question(13291, "Le golfe d'Arabie est aussi appelé golfe?", listOf("Persique", "Arabe", "Californie", "Mexique"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Le golfe Persique est le nom historique et officiel de cette étendue d'eau située entre l'Iran et la péninsule arabique, reconnu par les Nations unies et les organisations internationales."),
        Question(13292, "L'île de Chypre est divisée entre?", listOf("Grèce et Turquie", "Grèce et Chypre du Nord", "Chypre grecque et turque", "Tous les précédents"), 2, "Géographie", Difficulty.HARD, explanation = "Depuis l'invasion turque de 1974, l'île est séparée entre la République de Chypre (grecque) au sud et la République turque de Chypre du Nord (non reconnue internationalement) au nord."),
        Question(13293, "Le détroit de Palk sépare l'Inde de?", listOf("Sri Lanka", "Bangladesh", "Birmanie", "Thaïlande"), 0, "Géographie", Difficulty.HARD, explanation = "Le détroit de Palk relie le golfe du Bengale au golfe de Mannar et sépare l'État indien du Tamil Nadu du Sri Lanka."),
        Question(13294, "L'archipel de Lofoten appartient à?", listOf("Suède", "Finlande", "Norvège", "Islande"), 2, "Géographie", Difficulty.HARD, explanation = "L'archipel de Lofoten est situé au large de la côte nord-ouest de la Norvège, dans la mer de Norvège. Il fait partie du comté de Nordland, en Norvège."),
        Question(13295, "Le cap Racha est en?", listOf("Russie", "Géorgie", "Turquie", "Bulgarie"), 0, "Géographie", Difficulty.HARD, explanation = "Le cap Racha est situé sur la côte de la mer Noire, dans la péninsule de Crimée, qui est un territoire disputé mais actuellement contrôlé par la Russie."),
        Question(13296, "Le golfe de Gascogne borde?", listOf("France et Espagne", "France et Portugal", "Espagne et Portugal", "Irlande et France"), 0, "Géographie", Difficulty.HARD, explanation = "Le golfe de Gascogne est une partie de l'océan Atlantique située au sud-ouest de la France et au nord de l'Espagne."),
        Question(13297, "L'île de Corsica appartient à?", listOf("Italie", "France", "Espagne", "Suisse"), 1, "Géographie", Difficulty.EASY, explanation = "Corsica est le nom italien et corse de la Corse, une île de la mer Méditerranée qui est une collectivité territoriale française depuis 1768."),
        Question(13298, "Le détroit de Davis sépare le Canada du?", listOf("Groenland", "Labrador", "Terre-Neuve", "Archnichipel canadien"), 0, "Géographie", Difficulty.HARD, explanation = "Le détroit de Davis est un bras de mer situé entre l'île de Baffin (Canada) et le Groenland, reliant la mer du Labrador à la mer de Baffin."),
        Question(13299, "L'archipel de Vanuatu est situé où?", listOf("Polynésie", "Mélanésie", "Micronésie", "Océanie du Sud"), 1, "Géographie", Difficulty.HARD, explanation = "Vanuatu fait partie de la région océanienne de la Mélanésie, située dans le Pacifique Sud, au nord-est de l'Australie."),

        // NATURE (50 questions) - IDs 13300-13349
        Question(13300, "Les champignons appartiennent à quel groupe vivant?", listOf("Plantes", "Animaux", "Protistes", "Fungi"), 3, "Nature", Difficulty.EASY, explanation = "Les champignons forment leur propre règne biologique, les Fungi, distinct des plantes et des animaux, car ils possèdent des parois cellulaires de chitine et se nourrissent par absorption."),
        Question(13301, "Comment se reproduisent principalement les champignons?", listOf("Graines", "Spores", "Bourgeons", "Division cellulaire"), 1, "Nature", Difficulty.MEDIUM, explanation = "Les champignons se reproduisent principalement via des spores, des cellules reproductrices microscopiques libérées dans l'environnement pour germer et former de nouveaux individus."),
        Question(13302, "Les coraux sont des animaux ou des plantes?", listOf("Animaux", "Plantes", "Protistes", "Fungi"), 0, "Nature", Difficulty.EASY, explanation = "Les coraux sont des animaux marins appartenant à l'embranchement des cnidaires, comme les méduses. Ils vivent en colonies et construisent des squelettes calcaires."),
        Question(13303, "Les coraux forment des récifs en association avec?", listOf("Diatomées", "Algues zooxanthelles", "Bactéries", "Virus"), 1, "Nature", Difficulty.HARD, explanation = "Les coraux vivent en symbiose avec des algues microscopiques appelées zooxanthelles, qui leur fournissent l'énergie nécessaire à la construction de leur squelette calcaire, formant ainsi les récifs."),
        Question(13304, "Les bactéries sont unicellulaires. Possèdent-elles un noyau?", listOf("Oui", "Non", "Parfois", "Débattu"), 1, "Nature", Difficulty.EASY, explanation = "Les bactéries sont des organismes procaryotes, ce qui signifie qu'elles n'ont pas de noyau délimité par une membrane. Leur matériel génétique est libre dans le cytoplasme."),
        Question(13305, "La paroi cellulaire bactérienne est composée de?", listOf("Cellullose", "Peptidoglycane", "Lipides", "Protéines"), 1, "Nature", Difficulty.HARD, explanation = "Le peptidoglycane est un polymère unique aux bactéries, formé de sucres et d'acides aminés, qui confère rigidité et protection à leur paroi cellulaire."),
        Question(13306, "Les algues vertes sont des?", listOf("Bactéries", "Protistes", "Plantes", "Fungi"), 2, "Nature", Difficulty.MEDIUM, explanation = "Les algues vertes sont classées dans le règne végétal car elles réalisent la photosynthèse grâce à la chlorophylle."),
        Question(13307, "Comment se reproduisent les algues principalement?", listOf("Graines", "Spores", "Scission binaire", "Toutes les méthodes"), 3, "Nature", Difficulty.HARD, explanation = "Les algues peuvent se reproduire de manière asexuée par division cellulaire ou fragmentation, et sexuée par la fusion de gamètes, selon les espèces et les conditions environnementales."),
        Question(13308, "Les parasites vivent sur ou dans un?", listOf("Prédateur", "Hôte", "Proie", "Symbionte"), 1, "Nature", Difficulty.EASY, explanation = "Un parasite dépend d'un autre organisme, appelé hôte, pour se nourrir et se reproduire, souvent au détriment de ce dernier."),
        Question(13309, "La relation parasitaire est un exemple de?", listOf("Symbiose", "Prédation", "Compétition", "Mutualisme"), 0, "Nature", Difficulty.MEDIUM, explanation = "En biologie, la symbiose désigne toute interaction durable entre deux organismes, incluant le parasitisme où l'un profite au détriment de l'autre."),
        Question(13310, "La symbiose entre racine et champignon s'appelle?", listOf("Parasitisme", "Mycorhize", "Épiphytisme", "Commensalisme"), 1, "Nature", Difficulty.HARD, explanation = "Le terme mycorhize désigne l'association symbiotique entre les racines d'une plante et un champignon, permettant un échange de nutriments bénéfique aux deux organismes."),
        Question(13311, "La symbiose lichen résulte de l'association de quel et quoi?", listOf("Algue et bactérie", "Algue et champignon", "Bactérie et champignon", "Virus et cellule"), 1, "Nature", Difficulty.HARD, explanation = "Le lichen est un organisme composite issu de la symbiose entre un champignon et une algue (ou une cyanobactérie), où le champignon fournit un abri et l'algue produit de la nourriture par photosynthèse."),
        Question(13312, "Les biomes terrestres incluent tous sauf?", listOf("Toundra", "Savane", "Océan", "Désert"), 2, "Nature", Difficulty.MEDIUM, explanation = "Les biomes terrestres sont définis par leurs écosystèmes sur terre ferme, comme les forêts ou les déserts. L'océan est un biome aquatique, pas terrestre."),
        Question(13313, "Le biome de toundra se caractérise par?", listOf("Froid extrême", "Peu de précipitations", "Permafrost", "Tous les précédents"), 3, "Nature", Difficulty.MEDIUM, explanation = "La toundra est définie par un climat froid, un sol gelé (pergélisol), une végétation basse et une courte saison de croissance, ce qui rend toutes les caractéristiques précédentes correctes."),
        Question(13314, "Le biome de taïga est aussi appelé forêt?", listOf("Tropicale", "Tempérée", "Boréale", "Méditerranéenne"), 2, "Nature", Difficulty.MEDIUM, explanation = "La taïga est une forêt de conifères située dans les régions froides de l'hémisphère nord, ce qui lui vaut le nom de forêt boréale."),
        Question(13315, "Les champignons décomposeurs jouent un rôle crucial de?", listOf("Prédateur", "Producteur", "Nettoyeur", "Compétiteur"), 2, "Nature", Difficulty.MEDIUM, explanation = "Ils transforment la matière organique morte en éléments nutritifs pour le sol, agissant ainsi comme les recycleurs et nettoyeurs naturels des écosystèmes."),
        Question(13316, "Le mycélium est la partie du champignon qui?", listOf("Produit les spores", "Se reproduit", "Absorbe les nutriments", "Libère les spores"), 2, "Nature", Difficulty.HARD, explanation = "Le mycélium est un réseau de filaments souterrains qui permet au champignon de décomposer la matière organique et d'absorber les nutriments nécessaires à sa croissance."),
        Question(13317, "Les basidiomycètes produisent les spores dans??", listOf("Sporanges", "Basides", "Asques", "Zoospores"), 1, "Nature", Difficulty.HARD, explanation = "Les basidiomycètes, un groupe de champignons, produisent leurs spores sexuées sur des cellules spécialisées appelées basides, situées généralement à la surface des lames des champignons."),
        Question(13318, "Les ascomycètes sont les champignons qui?", listOf("Forment des cordes", "Produisent des asques", "Vivent sur le sol", "Parasitent les arbres"), 1, "Nature", Difficulty.HARD, explanation = "Les ascomycètes forment le plus grand embranchement des champignons, caractérisé par la production de spores sexuées dans des cellules spécialisées appelées asques."),
        Question(13319, "La formation de polypes coralliens demande?", listOf("Quelques jours", "Quelques années", "Plusieurs siècles", "Plusieurs millénaires"), 2, "Nature", Difficulty.HARD, explanation = "Les polypes coralliens sécrètent du carbonate de calcium pour former leur squelette, un processus extrêmement lent qui prend plusieurs siècles pour créer des récifs massifs."),
        Question(13320, "Le blanchiment des coraux est causé par?", listOf("Pollution", "Augmentation de température", "Acidification", "Tous les précédents"), 3, "Nature", Difficulty.HARD, explanation = "Le blanchiment des coraux résulte d'une combinaison de facteurs : l'augmentation de la température de l'eau, la pollution et l'acidification des océans, qui stressent les coraux et les poussent à expulser leurs algues symbiotiques."),
        Question(13321, "Les bactéries photosynthétiques produisent de l'?", listOf("Azote", "Oxygène", "Méthane", "Dioxyde de carbone"), 1, "Nature", Difficulty.MEDIUM, explanation = "Les bactéries photosynthétiques, comme les cyanobactéries, utilisent la lumière solaire pour convertir le dioxyde de carbone et l'eau en énergie, libérant de l'oxygène comme sous-produit."),
        Question(13322, "La conjugaison bactérienne est un processus de?", listOf("Reproduction", "Transfert d'ADN", "Respiration", "Photosynthèse"), 1, "Nature", Difficulty.HARD, explanation = "La conjugaison bactérienne permet le transfert d'ADN d'une bactérie donneuse à une bactérie receveuse via un pilus, favorisant la diversité génétique."),
        Question(13323, "Les algues calcaires construisent les récifs par sécrétions de?", listOf("Calcite", "Aragonite", "Carbonate de calcium", "Tous les précédents"), 3, "Nature", Difficulty.HARD, explanation = "Les algues calcaires sécrètent du carbonate de calcium sous forme d'aragonite, de calcite et de magnésium, contribuant ainsi à la construction des récifs coralliens."),
        Question(13324, "Le plasmodesme est un pore de connexion entre?", listOf("Cellules du même organisme", "Cellules d'organismes différents", "Noyau et cytoplasme", "Chloroplaste et mitochondrie"), 0, "Nature", Difficulty.HARD, explanation = "Le plasmodesme est un canal microscopique qui traverse les parois cellulaires des végétaux, permettant les échanges entre cellules adjacentes d'un même organisme."),
        Question(13325, "Les spirochètes sont des bactéries de forme?", listOf("Sphérique", "Bacille", "Spirale", "Fusiforme"), 2, "Nature", Difficulty.HARD, explanation = "Le terme \"spirochète\" vient du grec \"speira\" (spirale) et \"chaite\" (cheveu), désignant leur forme hélicoïdale caractéristique."),
        Question(13326, "Les archées diffèrent des bactéries par la?", listOf("Forme", "Reproduction", "Composition membranaire", "Localisation"), 2, "Nature", Difficulty.HARD, explanation = "Les archées possèdent des lipides membranaires aux chaînes carbonées ramifiées liées par des liaisons éther, contrairement aux bactéries dont les membranes sont composées d'acides gras à liaisons ester."),
        Question(13327, "Le zooplancton du récif corallien inclut?", listOf("Copépodes", "Larves de poisson", "Crustacés minuscules", "Tous les précédents"), 3, "Nature", Difficulty.HARD, explanation = "Le zooplancton des récifs coralliens est très diversifié et comprend des larves de poissons, des crustacés microscopiques et des méduses, entre autres organismes."),
        Question(13328, "La chlorophylle est le pigment principal de la?", listOf("Photosynthèse", "Respiration", "Reproduction", "Croissance"), 0, "Nature", Difficulty.EASY, explanation = "La chlorophylle capte l'énergie lumineuse nécessaire à la photosynthèse, processus par lequel les plantes transforment le dioxyde de carbone et l'eau en glucose et oxygène."),
        Question(13329, "Les algues rouges doivent leur couleur à la phyco...?", listOf("Mycine", "Érythrine", "Billine", "Anthocyane"), 1, "Nature", Difficulty.HARD, explanation = "La phycoérythrine, un pigment rouge, est responsable de la couleur des algues rouges, leur permettant de capter la lumière bleue en profondeur."),
        Question(13330, "Le parasite Plasmodium cause la?", listOf("Dengue", "Malaria", "Fièvre jaune", "Zika"), 1, "Nature", Difficulty.MEDIUM, explanation = "Plasmodium est un parasite transmis par la piqûre de moustiques Anophèles, qui provoque la malaria (ou paludisme), une maladie infectieuse grave."),
        Question(13331, "La trypanosome est un parasite causant la??", listOf("Malaria", "Maladie du sommeil", "Trypanosomose", "Maladie de Chagas"), 1, "Nature", Difficulty.HARD, explanation = "Transmise par la mouche tsé-tsé, la trypanosome provoque la maladie du sommeil, une infection parasitaire touchant principalement l'Afrique subsaharienne."),
        Question(13332, "Les nématodes parasitaires comprennent?", listOf("Ascaris", "Ankylostome", "Filaria", "Tous les précédents"), 3, "Nature", Difficulty.HARD, explanation = "Les nématodes parasitaires incluent des espèces affectant les plantes, les animaux et les humains, comme les ascaris ou les ankylostomes, ce qui justifie la réponse \"Tous les précédents\"."),
        Question(13333, "La photosynthèse utilise l'énergie de??", listOf("Chaleur", "Lumière", "Chimie", "Électricité"), 1, "Nature", Difficulty.EASY, explanation = "La photosynthèse est le processus par lequel les plantes transforment l'énergie lumineuse en énergie chimique, principalement grâce à la chlorophylle."),
        Question(13334, "La chimiolithotrophie est une stratégie de??", listOf("Photosynthèse", "Métabolisme chimique", "Fermentation", "Respiration"), 1, "Nature", Difficulty.HARD, explanation = "La chimiolithotrophie désigne un type de métabolisme où des organismes tirent leur énergie de l'oxydation de composés chimiques inorganiques, comme le soufre ou le fer, plutôt que de la lumière."),
        Question(13335, "Les ectomycorrhizes enveloppent les racines de??", listOf("Couche blanche", "Filet blanc", "Réseau dense", "Sheath"), 0, "Nature", Difficulty.HARD, explanation = "Les ectomycorhizes forment un manteau fongique autour des racines, souvent de couleur blanche, qui facilite les échanges nutritifs entre le champignon et la plante."),
        Question(13336, "Les endomycorrhizes pénètrent les cellules racinaires. Vrai ou Faux?", listOf("Vrai", "Faux", "Rarement", "Toujours"), 0, "Nature", Difficulty.HARD, explanation = "Les endomycorhizes, contrairement aux ectomycorhizes, forment des structures intracellulaires comme des arbuscules à l'intérieur des cellules racinaires, ce qui facilite les échanges nutritifs."),
        Question(13337, "Le thalus lichénique est composé de?", listOf("Cordes fongiques", "Filaments d'algue", "Hyphe et algue", "Spores et hyphes"), 2, "Nature", Difficulty.HARD, explanation = "Le lichen est un organisme symbiotique formé par l'association d'un champignon (hyphes) et d'une algue, constituant ainsi le thalle lichénique."),
        Question(13338, "Les lichens sont indicateurs de??", listOf("Pollens", "Pollution", "Âge du sol", "Humidity"), 1, "Nature", Difficulty.MEDIUM, explanation = "Les lichens sont très sensibles à la qualité de l'air, notamment aux composés soufrés et azotés, ce qui en fait des bio-indicateurs fiables de la pollution atmosphérique."),
        Question(13339, "Le biome de savane se caractérise par?", listOf("Graminées et arbres épars", "Arbres denses", "Absence de végétation", "Herbivores carnivores"), 0, "Nature", Difficulty.MEDIUM, explanation = "La savane est un biome tropical où les précipitations sont trop faibles pour soutenir une forêt dense, mais suffisantes pour empêcher un désert, favorisant ainsi les graminées et quelques arbres dispersés."),
        Question(13340, "La forêt tropicale humide couvre approximativement combien de l'Terre?", listOf("5%", "10%", "15%", "20%"), 1, "Nature", Difficulty.HARD, explanation = "Les forêts tropicales humides ne couvrent qu'environ 10% de la surface terrestre, mais elles abritent plus de la moitié des espèces animales et végétales de la planète."),
        Question(13341, "Les biomes aquatiques freshwater incluent?", listOf("Lacs", "Rivières", "Marais", "Tous les précédents"), 3, "Nature", Difficulty.MEDIUM, explanation = "Les biomes d'eau douce regroupent les lacs, rivières, étangs et zones humides, car ils partagent une faible salinité et des écosystèmes interconnectés."),
        Question(13342, "L'estuaire est une zone de mélange entre l'eau?", listOf("Douce et salée", "Chaude et froide", "Stagnante et courante", "Superficielle et profonde"), 0, "Nature", Difficulty.MEDIUM, explanation = "L'estuaire est la zone de transition où un fleuve d'eau douce rencontre l'eau salée de la mer, créant un mélange appelé eau saumâtre."),
        Question(13343, "Les bioluminescentes bactéries produisent de la lumière par??", listOf("Photosynthèse", "Chimioluminescence", "Fluorescence", "Réflexion"), 1, "Nature", Difficulty.HARD, explanation = "La lumière produite par les bactéries bioluminescentes résulte d'une réaction chimique impliquant une enzyme appelée luciférase, qui oxyde un substrat (la luciférine) en émettant de l'énergie lumineuse. Ce processus est un exemple de chimioluminescence, où l'énergie chimique est convertie directement en lumière sans chaleur."),
        Question(13344, "Les mouches du vinaigre hébergent des bactéries dans leur??", listOf("Estomac", "Intestin", "Symbiontes", "Tous les organes"), 2, "Nature", Difficulty.HARD, explanation = "Les mouches du vinaigre entretiennent une relation symbiotique avec des bactéries, notamment Wolbachia, qui vivent dans leurs cellules et influencent leur reproduction."),
        Question(13345, "La relation anemone-clownfish est un exemple de??", listOf("Prédation", "Mutualisme", "Parasitisme", "Commensalisme"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le poisson-clown trouve refuge dans les tentacules de l'anémone, qui le protège des prédateurs, tandis que le poisson nettoie l'anémone et l'aère en nageant. Cette interaction bénéfique aux deux espèces est un cas classique de mutualisme."),
        Question(13346, "Les arthropodes hébergent combien de bactéries?", listOf("Centaines", "Milliers", "Millions", "Milliards"), 3, "Nature", Difficulty.HARD, explanation = "Les arthropodes, comme les insectes, abritent des milliards de bactéries symbiotiques dans leur microbiote intestinal, essentiel à leur digestion et défense immunitaire."),
        Question(13347, "Les biofilms bactériens présentent une résistance accrue aux??", listOf("Antibiotiques", "Antiseptiques", "Système immunitaire", "Tous les précédents"), 3, "Nature", Difficulty.HARD, explanation = "Les biofilms bactériens sont des communautés structurées de bactéries enrobées dans une matrice protectrice, ce qui les rend résistants aux antibiotiques, aux désinfectants et au système immunitaire."),
        Question(13348, "Les champignons endomycètes produisent les spores dans??", listOf("Sporanges", "Basides", "Asques", "Zoosporanges"), 2, "Nature", Difficulty.HARD, explanation = "Les champignons endomycètes, aussi appelés ascomycètes, produisent leurs spores sexuées dans des cellules spécialisées en forme de sac appelées asques."),
        Question(13349, "Le transfert horizontal de gènes entre espèces bactériennes est un?", listOf("Mythe", "Phénomène rare", "Phénomène courant", "Processus limité"), 2, "Nature", Difficulty.HARD, explanation = "Les bactéries échangent fréquemment du matériel génétique via la conjugaison, la transformation ou la transduction, ce qui rend ce transfert horizontal courant dans leur adaptation rapide à l'environnement."),

        // CULTURE (50 questions) - IDs 13350-13399
        Question(13350, "L'opéra est un art dramatique combinant musique et??", listOf("Danse", "Théâtre", "Chant", "Tous les précédents"), 3, "Culture", Difficulty.EASY, explanation = "L'opéra combine musique, chant, mise en scène, décors et parfois danse, ce qui en fait un art total intégrant tous ces éléments."),
        Question(13351, "Quel pays a produit les plus grands opéras du 18e siècle?", listOf("France", "Italie", "Allemagne", "Angleterre"), 1, "Culture", Difficulty.MEDIUM, explanation = "L'opéra est né en Italie au XVIIe siècle, et au XVIIIe siècle, des compositeurs italiens comme Haendel, Vivaldi et Mozart (pour ses opéras italiens) ont dominé ce genre musical."),
        Question(13352, "Le ballet est un art du mouvement corporel. Depuis quand?", listOf("15e siècle", "16e siècle", "17e siècle", "18e siècle"), 1, "Culture", Difficulty.MEDIUM, explanation = "Le ballet codifié apparaît à la cour d'Italie puis de France au 16e siècle, notamment avec le \"Ballet comique de la reine\" en 1581."),
        Question(13353, "Quel ballet de Tchaïkovski est le plus célèbre?", listOf("Roméo et Juliet", "Le Lac des cygnes", "Casse-Noisette", "La Belle au bois dormant"), 1, "Culture", Difficulty.MEDIUM, explanation = "Le Lac des cygnes est le ballet le plus célèbre de Tchaïkovski, créé en 1877, et reste une œuvre emblématique du répertoire classique grâce à sa musique et son histoire tragique."),
        Question(13354, "Le théâtre grec antique utilisait des?", listOf("Masques", "Maquillage", "Perruques", "Costumes amples"), 0, "Culture", Difficulty.MEDIUM, explanation = "Les acteurs du théâtre grec antique portaient des masques pour incarner différents personnages et amplifier leur voix dans les grands amphithéâtres."),
        Question(13355, "La Comédie italienne (Commedia dell'arte) utilisait des personnages??", listOf("Historiques", "Archétypaux stéréotypés", "Royaux", "Mythologiques"), 1, "Culture", Difficulty.HARD, explanation = "La Commedia dell'arte reposait sur des personnages fixes et reconnaissables comme Arlequin, Pantalone ou Colombine, chacun avec un costume, un masque et des traits de caractère immuables."),
        Question(13356, "Shakespeare a écrit ses pièces en quelle langue?", listOf("Latin", "Français", "Anglais élisabéthain", "Grec"), 2, "Culture", Difficulty.EASY, explanation = "Shakespeare écrivait à l'époque élisabéthaine, où l'anglais différait de l'anglais moderne dans son vocabulaire et sa grammaire."),
        Question(13357, "La sculpture grecque antique a atteint son sommet à la période??", listOf("Archaïque", "Classique", "Hellénistique", "Romaine"), 1, "Culture", Difficulty.HARD, explanation = "La période classique (Ve-IVe siècles av. J.-C.) est considérée comme l'apogée de la sculpture grecque, marquée par la recherche d'harmonie, de proportion et de naturalisme, avec des artistes comme Phidias ou Polyclète."),
        Question(13358, "Le David de Michel-Ange est une sculpture de la Renaissance??", listOf("Italienne", "Française", "Flamande", "Espagnole"), 0, "Culture", Difficulty.MEDIUM, explanation = "Michel-Ange, artiste majeur de la Renaissance, a sculpté le David à Florence, en Italie, entre 1501 et 1504."),
        Question(13359, "La céramique grecque antique inclut le style??", listOf("À figures rouges", "À figures noires", "Polychrome", "A et B"), 3, "Culture", Difficulty.HARD, explanation = "La céramique grecque antique se divise principalement entre le style à figures noires (figures sombres sur fond clair) et le style à figures rouges (figures claires sur fond sombre), tous deux majeurs dans l'art grec."),
        Question(13360, "La calligraphie est un art d'écriture particulièrement développé en??", listOf("Occident", "Asie de l'Est", "Moyen-Orient", "Afrique du Nord"), 1, "Culture", Difficulty.MEDIUM, explanation = "La calligraphie est un art majeur en Asie de l'Est, notamment en Chine, au Japon et en Corée, où elle est pratiquée depuis des siècles avec des outils comme le pinceau et l'encre."),
        Question(13361, "La calligraphie arabe utilise une écriture??", listOf("Carrée", "Cursive", "Géométrique", "Tous les styles"), 3, "Culture", Difficulty.HARD, explanation = "La calligraphie arabe regroupe plusieurs styles d'écriture, comme le coufique, le naskh ou le thuluth, chacun ayant ses propres règles esthétiques."),
        Question(13362, "Le tatouage traditionnel japonais (irezumi) utilise quels pigments?", listOf("Naturels", "Chimiques", "Historiquement naturels", "Modernes synthétiques"), 2, "Culture", Difficulty.HARD, explanation = "L’encre traditionnelle irezumi était fabriquée à partir de pigments naturels, comme le noir de carbone ou des minéraux, avant l’arrivée des encres synthétiques modernes."),
        Question(13363, "Le tatouage polynésien raconte l'histoire du porteur. Vrai ou Faux?", listOf("Vrai", "Faux", "Partiellement", "Débattu"), 0, "Culture", Difficulty.MEDIUM, explanation = "Dans la culture polynésienne, chaque motif et placement du tatouage a une signification précise, retraçant la généalogie, les exploits et le statut social de la personne."),
        Question(13364, "Le cirque moderne débuta au??", listOf("17e siècle", "18e siècle", "19e siècle", "20e siècle"), 2, "Culture", Difficulty.HARD, explanation = "Le cirque moderne tel qu'on le connaît, avec chapiteau et numéros équestres, a été inventé à Londres par Philip Astley dans les années 1770, ce qui correspond au 18e siècle."),
        Question(13365, "Le Cirque du Soleil provient de quel pays?", listOf("Usa", "France", "Canada", "Mexique"), 2, "Culture", Difficulty.MEDIUM, explanation = "Fondé en 1984 par Guy Laliberté et Daniel Gauthier à Baie-Saint-Paul, au Québec, le Cirque du Soleil est une entreprise canadienne."),
        Question(13366, "L'acrobatie circassienne inclut??", listOf("Jonglerie", "Trapèze", "Équilibre", "Tous les précédents"), 3, "Culture", Difficulty.MEDIUM, explanation = "L'acrobatie circassienne englobe diverses disciplines comme les sauts, les pyramides humaines, les équilibres et les portés, donc toutes les options proposées sont correctes."),
        Question(13367, "La pantomime est un art du théâtre utilisant??", listOf("Parole", "Silence avec gestes", "Danse", "Musique"), 1, "Culture", Difficulty.MEDIUM, explanation = "La pantomime repose sur l'expression corporelle et les gestes pour raconter une histoire, sans paroles ni sons."),
        Question(13368, "Marcel Marceau était un maître de la??", listOf("Danse", "Pantomime", "Théâtre", "Cirque"), 1, "Culture", Difficulty.MEDIUM, explanation = "Marcel Marceau est mondialement reconnu pour avoir popularisé l'art du mime, ou pantomime, notamment à travers son personnage de Bip."),
        Question(13369, "La Comédia francese se joue au Théâtre??", listOf("Des Variétés", "Français", "du Palais-Royal", "de la Sourdière"), 1, "Culture", Difficulty.HARD, explanation = "La Comédie-Française, aussi appelée le Théâtre-Français, est une institution théâtrale nationale située à Paris. Elle tire son nom de la langue française et de son répertoire classique."),
        Question(13370, "Le théâtre du Grand Guignol était connu pour??", listOf("Horreur et gore", "Tragédie", "Comédie légère", "Farce"), 0, "Culture", Difficulty.HARD, explanation = "Fondé à Paris en 1897, ce théâtre se spécialisait dans des pièces naturalistes mettant en scène des meurtres, tortures et violences graphiques, d'où son nom devenu synonyme d'horreur."),
        Question(13371, "Molière écrivait ses pièces en quelle langue?", listOf("Latin", "Français", "Italien", "Grec"), 1, "Culture", Difficulty.EASY, explanation = "Molière, dramaturge du XVIIe siècle, écrivait en français, la langue de la cour et de la littérature de son époque."),
        Question(13372, "La Sculpture Renaissance italienne se concentrait sur??", listOf("Abstraction", "Réalisme et anatomie", "Géométrie", "Symbolisme"), 1, "Culture", Difficulty.HARD, explanation = "La sculpture de la Renaissance italienne s'inspirait de l'art antique et des études anatomiques, visant à représenter le corps humain avec précision et naturalisme."),
        Question(13373, "Donatello était un sculpteur de la Renaissance en??", listOf("France", "Italie", "Flandre", "Espagne"), 1, "Culture", Difficulty.HARD, explanation = "Donatello était un sculpteur majeur de la première Renaissance, actif principalement à Florence et dans d'autres cités italiennes."),
        Question(13374, "La céramique médiévale blanche et bleue provient de??", listOf("Japon", "Chine", "Perse", "Espagne"), 1, "Culture", Difficulty.HARD, explanation = "La céramique blanche et bleue, caractéristique de la porcelaine chinoise, a été perfectionnée sous la dynastie Yuan et Ming avant d'être exportée en Europe."),
        Question(13375, "Les porcelaines de Delft imitaient le style??", listOf("Chinois", "Japonais", "Persan", "Turc"), 0, "Culture", Difficulty.HARD, explanation = "Les porcelaines de Delft, produites aux Pays-Bas à partir du XVIIe siècle, imitaient le style des porcelaines chinoises importées par la Compagnie néerlandaise des Indes orientales."),
        Question(13376, "Le Kabuki est un art dramatique du??", listOf("Japon", "Chine", "Thaïlande", "Viêt-Nam"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le Kabuki est une forme de théâtre traditionnel japonais, mêlant chant, danse et jeu d'acteur, apparu au début de l'époque d'Edo."),
        Question(13377, "Kabuki utilise traditionally quels acteurs?", listOf("Hommes et femmes", "Seulement hommes", "Seulement femmes", "Cela a varié"), 1, "Culture", Difficulty.HARD, explanation = "Le Kabuki, théâtre traditionnel japonais né au XVIIe siècle, interdit la présence des femmes sur scène depuis 1629 pour des raisons morales, les rôles féminins étant joués par des acteurs masculins spécialisés (onnagata)."),
        Question(13378, "Le Noh est un art dramatique japonais ancien et??", listOf("Rapide", "Lent et poétique", "Comique", "Bruyant"), 1, "Culture", Difficulty.HARD, explanation = "Le Noh se caractérise par des mouvements lents et stylisés, accompagnés de chants et de musique, visant à créer une atmosphère poétique et méditative."),
        Question(13379, "L'art du henna est traditionnel en??", listOf("Asie du Sud", "Moyen-Orient", "Afrique du Nord", "Tous les précédents"), 3, "Culture", Difficulty.MEDIUM, explanation = "Le henna est traditionnellement utilisé en Inde, au Pakistan, au Bangladesh et au Sri Lanka pour les célébrations comme les mariages, ainsi qu’au Moyen-Orient et en Afrique du Nord."),
        Question(13380, "La calligraphie chinoise utilise le??", listOf("Stylo", "Pinceau", "Plume", "Crayon"), 1, "Culture", Difficulty.EASY, explanation = "L’outil traditionnel de la calligraphie chinoise est le pinceau, utilisé avec de l’encre de Chine sur du papier de riz ou de la soie."),
        Question(13381, "Le Bunraku est un art de marionnettes??", listOf("Coréen", "Thaï", "Japonais", "Indonésien"), 2, "Culture", Difficulty.HARD, explanation = "Le bunraku est une forme de théâtre de marionnettes traditionnelle originaire du Japon, apparue au XVIIe siècle à Osaka."),
        Question(13382, "L'art corporel body painting utilise??", listOf("Peintures temporaires", "Maquillage", "Pigments naturels", "Tous les précédents"), 3, "Culture", Difficulty.MEDIUM, explanation = "Le body painting peut utiliser de la peinture corporelle, des pinceaux, des éponges et d'autres outils, ainsi que des techniques comme l'aérographe, englobant ainsi tous les éléments précédents."),
        Question(13383, "Le scarification est une pratique traditionnelle en??", listOf("Afrique", "Asie", "Océanie", "Amérique"), 0, "Culture", Difficulty.MEDIUM, explanation = "La scarification est une pratique ancestrale répandue dans de nombreuses ethnies africaines, servant de marque d'identité, de rite de passage ou d'ornement corporel."),
        Question(13384, "La broderie dentelle-à-l'aiguille vient de??", listOf("Venise", "Bruxelles", "Alençon", "Bruges"), 0, "Culture", Difficulty.HARD, explanation = "La broderie dentelle-à-l'aiguille est une technique née à Venise au XVIe siècle, où elle était prisée pour sa finesse et utilisée dans les vêtements et le linge d'église."),
        Question(13385, "Le tissage Navajo est une tradition amérindienne de??", listOf("Poterie", "Textiles", "Sculpture", "Peinture"), 1, "Culture", Difficulty.MEDIUM, explanation = "Le tissage Navajo est une pratique ancestrale de création de couvertures, tapis et vêtements, utilisant des métiers à tisser verticaux et des motifs géométriques symboliques."),
        Question(13386, "La céramique Raku provient du??", listOf("Japon", "Chine", "Corée", "Thaïlande"), 0, "Culture", Difficulty.HARD, explanation = "Le Raku est une technique de céramique développée au Japon au XVIe siècle, associée à la cérémonie du thé zen."),
        Question(13387, "Le théâtre Kathak kal provient de quelle région?", listOf("Inde du Nord", "Inde du Sud", "Bangladesh", "Pakistan"), 0, "Culture", Difficulty.HARD, explanation = "Le Kathakali est une forme de théâtre dansé originaire du Kerala, en Inde du Sud, tandis que le Kathak, qui lui est souvent confondu, est une danse classique de l'Inde du Nord."),
        Question(13388, "La danse Bharatanatyam est une danse classique de l'??", listOf("Inde du Nord", "Inde du Sud", "Sri Lanka", "Indonésie"), 1, "Culture", Difficulty.HARD, explanation = "Le Bharatanatyam est une danse classique originaire du Tamil Nadu, dans le sud de l'Inde, reconnue pour ses mouvements précis et ses expressions narratives."),
        Question(13389, "Le théâtre Peking Opera est un art dramatique du??", listOf("Japon", "Chine", "Corée", "Thaïlande"), 1, "Culture", Difficulty.MEDIUM, explanation = "Le Peking Opera, ou opéra de Pékin, est une forme d’art dramatique traditionnel chinois mêlant chant, danse et acrobaties."),
        Question(13390, "Le maquillage d'opéra Peking utilise des motifs appelés??", listOf("Lianpu", "Yuanpu", "Facepu", "Taipu"), 0, "Culture", Difficulty.HARD, explanation = "Le Lianpu désigne les motifs de maquillage codifiés de l'opéra de Pékin, chaque couleur et dessin symbolisant le caractère du personnage (héros, traître, etc.)."),
        Question(13391, "L'art du Graffiti provient du??", listOf("Brooklyn", "Los Angeles", "Chicago", "New York"), 3, "Culture", Difficulty.MEDIUM, explanation = "Le graffiti moderne est né dans les années 1970 à New York, où des jeunes des quartiers populaires taguaient les murs et les métros pour marquer leur territoire et exprimer leur identité."),
        Question(13392, "La Street Art utilise des techniques comme??", listOf("Peinture", "Pochoir", "Collage", "Tous les précédents"), 3, "Culture", Difficulty.MEDIUM, explanation = "Le street art englobe diverses techniques comme le pochoir, la peinture au rouleau, les collages, les mosaïques et le graffiti, ce qui rend la réponse \"Tous les précédents\" correcte."),
        Question(13393, "Le Dadaïsme était un mouvement artistique du??", listOf("18e siècle", "19e siècle", "20e siècle (début)", "20e siècle (milieu)"), 2, "Culture", Difficulty.HARD, explanation = "Le Dadaïsme est né pendant la Première Guerre mondiale, vers 1916, et s'est développé dans les années 1920, ce qui le place au début du 20e siècle."),
        Question(13394, "Le Surréalisme explorait l'??", listOf("Réalité", "Inconscient", "Logique", "Raison"), 1, "Culture", Difficulty.MEDIUM, explanation = "André Breton, chef de file du surréalisme, définit le mouvement comme un automatisme psychique pur visant à exprimer le fonctionnement réel de la pensée, en l'absence de tout contrôle exercé par la raison."),
        Question(13395, "L'art Abstrait rejetait la??", listOf("Couleur", "Forme", "Représentation réaliste", "Texture"), 2, "Culture", Difficulty.MEDIUM, explanation = "L'art abstrait s'est développé au début du XXe siècle en rompant avec la figuration et la représentation du monde visible, privilégiant formes, couleurs et émotions pures."),
        Question(13396, "Le Pop Art utilisait des images de??", listOf("Nature", "Culture populaire", "Histoire", "Religion"), 1, "Culture", Difficulty.MEDIUM, explanation = "Le Pop Art s'est développé dans les années 1950-1960 en s'inspirant des objets et symboles de la société de consommation, comme les publicités, les bandes dessinées ou les stars médiatiques."),
        Question(13397, "Andy Warhol était un artiste Pop connu pour??", listOf("Sculptures", "Lithographies", "Sérigraphies", "Peintures abstraites"), 2, "Culture", Difficulty.MEDIUM, explanation = "Andy Warhol a popularisé la sérigraphie dans les années 1960 pour reproduire en série des images de consommation, comme les boîtes de soupe Campbell ou les portraits de Marilyn Monroe."),
        Question(13398, "L'art minimaliste se concentre sur??", listOf("Complexité", "Ornamentation", "Formes simples", "Détails"), 2, "Culture", Difficulty.HARD, explanation = "L'art minimaliste, apparu dans les années 1960, rejette l'expressionnisme et l'ornementation pour se concentrer sur des formes géométriques simples, des couleurs unies et des matériaux industriels."),
        Question(13399, "Bansky est un artiste contemporain connu pour ses??", listOf("Sculptures", "Graffitis politiques", "Peintures", "Installations"), 1, "Culture", Difficulty.MEDIUM, explanation = "Banksy réalise des pochoirs muraux satiriques sur des thèmes comme la guerre ou le capitalisme, ce qui en fait des graffitis politiques.")
    )
}
